const SR = "https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/";
const KN = "https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/";
const CIM = "https://docs.splunk.com/Documentation/CIM/latest/User/Overview";
const SUB = "https://docs.splunk.com/Documentation/Splunk/latest/Search/Aboutsubsearches";
const PIV = "https://docs.splunk.com/Documentation/Splunk/latest/Pivot/IntroductiontoPivot";

const QUESTIONS = [
 // ---- Module 1: Transforming Commands & Visualizations ----
 {q:`Which command <b>always</b> places <code>_time</code> on the x-axis and auto-buckets by time?`,
  o:[`<code>chart</code>`,`<code>timechart</code>`,`<code>stats</code>`,`<code>table</code>`],a:[1],
  e:`<b>timechart</b> forces <code>_time</code> onto the x-axis. <code>chart</code> lets you pick the x-axis with <code>over</code>/<code>by</code>.`,d:SR+"Timechart"},
 {q:`What is required to populate the Visualization tab (build a chart)?`,
  o:[`A lookup`,`A transforming command (stats/chart/timechart/top/rare)`,`The <code>table</code> command`,`A subsearch`],a:[1],
  e:`Only a <b>transforming command</b> produces the statistics table that visualizations render from. <code>table</code> is display-only and is <i>not</i> transforming.`,d:SR+"Stats"},
 {q:`Which command compares values across a chosen (non-time) x-axis using <code>over</code> and <code>by</code>?`,
  o:[`<code>timechart</code>`,`<code>chart</code>`,`<code>stats</code>`,`<code>eval</code>`],a:[1],
  e:`<b>chart</b> supports <code>over X by Y</code> - X is the x-axis, Y splits into series. <code>timechart</code> is always <code>_time</code>.`,d:SR+"Chart"},
 {q:`Which <code>stats</code> function returns a <b>de-duplicated, sorted</b> list of values, and which returns <b>all values in order (with duplicates)</b>?`,
  o:[`<code>list()</code> / <code>values()</code>`,`<code>values()</code> / <code>list()</code>`,`<code>dc()</code> / <code>count()</code>`,`<code>uniq()</code> / <code>mvlist()</code>`],a:[1],
  e:`<b>values()</b> = unique + sorted; <b>list()</b> = every value in event order (keeps duplicates).`,d:SR+"Stats"},
 {q:`The <code>top</code> command automatically returns which two fields?`,
  o:[`<code>sum</code> and <code>avg</code>`,`<code>count</code> and <code>percent</code>`,`<code>_time</code> and <code>host</code>`,`<code>min</code> and <code>max</code>`],a:[1],
  e:`<b>top</b> adds <code>count</code> and <code>percent</code>. <code>rare</code> (its opposite) does the same for least-common values.`,d:SR+"Top"},
 {q:`When using <code>top</code>, adding a <code>BY</code> clause does what?`,
  o:[`Sorts the results`,`Groups the results so you get the top values for each group`,`Limits results to one row`,`Removes duplicates`],a:[1],
  e:`<code>top user by region</code> returns the most common users <b>for each region</b> - it groups the ranking per category.`,d:SR+"Top"},
 {q:`Which command overlays a <b>moving average</b> (sma/ema/wma) on a chart?`,
  o:[`<code>sparkline</code>`,`<code>trendline</code>`,`<code>addtotals</code>`,`<code>eventstats</code>`],a:[1],
  e:`<b>trendline</b> computes a moving average, e.g. <code>trendline sma5(count)</code>. Types: <b>sma</b>, <b>ema</b>, <b>wma</b>.`,d:SR+"Trendline"},
 {q:`How do you add an inline mini-chart inside a <code>stats</code> table?`,
  o:[`<code>trendline()</code>`,`<code>sparkline()</code> used inside stats`,`<code>gauge()</code>`,`<code>timechart</code>`],a:[1],
  e:`<b>sparkline()</b> is used inside <code>stats</code>: <code>stats sparkline(count) count by host</code>.`,d:SR+"Stats"},
 {q:`By default, how many distinct series do <code>chart</code>/<code>timechart</code> show before grouping the rest into "OTHER", and how do you show them all?`,
  o:[`5; use <code>useother=t</code>`,`10; use <code>limit=0</code>`,`20; use <code>span=0</code>`,`100; use <code>usenull=f</code>`],a:[1],
  e:`Default is the <b>top 10</b>; the rest roll into <b>"OTHER"</b>. <b><code>limit=0</code></b> shows every split-by value (no OTHER).`,d:SR+"Chart"},
 {q:`With <code>chart count over host by status limit=0</code>, what does <code>limit=0</code> control?`,
  o:[`The number of x-axis (host) values`,`The number of split-by (status) series - 0 means show all`,`The time span`,`The row count`],a:[1],
  e:`<code>limit</code> caps the <b>split-by</b> (<code>by</code>) series, not the x-axis. <code>limit=0</code> = show all series, no "OTHER".`,d:SR+"Chart"},
 {q:`Which command adds a total column per row (<code>row=t</code>) and/or a totals row (<code>col=t</code>)?`,
  o:[`<code>addtotals</code>`,`<code>appendpipe</code>`,`<code>fillnull</code>`,`<code>eventstats</code>`],a:[0],
  e:`<b>addtotals</b>: <code>row=t</code> adds a total column across each row; <code>col=t</code> adds a totals row.`,d:SR+"Addtotals"},
 {q:`Which command buckets a continuous field into ranges and underlies how <code>timechart</code> groups time?`,
  o:[`<code>bin</code> (a.k.a. <code>bucket</code>)`,`<code>dedup</code>`,`<code>fields</code>`,`<code>rename</code>`],a:[0],
  e:`<b>bin</b>/<b>bucket</b> discretizes a field (e.g. <code>bin span=5m _time</code>); <code>timechart</code> uses it internally.`,d:SR+"Bin"},

 // ---- Module 2: Filtering & Formatting Results ----
 {q:`In <code>where</code>, a <b>double-quoted</b> string is a ___, and an <b>unquoted/single-quoted</b> string is a ___.`,
  o:[`field, field value`,`field value, field`,`integer, field`,`field, integer`],a:[1],
  e:`<b>Double quotes = a field VALUE</b> (literal). <b>Unquoted/single-quoted = a FIELD name</b>. So <code>where a="b"</code> vs <code>where a=b</code> mean different things.`,d:SR+"Where"},
 {q:`Which is TRUE about <code>where</code> vs <code>search</code>?`,
  o:[`search can compare field-to-field; where cannot`,`where uses eval expressions and can compare field-to-field; search cannot`,`Both support the <code>*</code> wildcard`,`where filters on raw keywords`],a:[1],
  e:`<b>where</b> uses eval expressions and can compare <b>field to field</b> (<code>bytes_in>bytes_out</code>). <code>search</code> only compares a field to a literal and matches keywords.`,d:SR+"Where"},
 {q:`Which command removes the <code>status</code> field while keeping all others?`,
  o:[`<code>| fields status</code>`,`<code>| fields - status</code>`,`<code>| table status</code>`,`<code>| dedup status</code>`],a:[1],
  e:`<b><code>fields - status</code></b> removes it; <code>fields status</code> keeps only status. Internal <code>_</code> fields aren't removed unless named.`,d:SR+"Fields"},
 {q:`How does <code>table</code> differ from <code>fields</code>?`,
  o:[`table is faster and runs on indexers`,`table is display-only (keeps column order, not transforming); fields trims the field list for performance`,`They are identical`,`fields builds charts`],a:[1],
  e:`<b>table</b> = presentation (ordered columns, not a transforming command). <b>fields</b> = performance (trim early; <code>fields +</code> is a key optimization).`,d:SR+"Table"},
 {q:`What does <code>dedup host</code> do by default?`,
  o:[`Removes all events for each host`,`Keeps the first event for each unique host value`,`Sorts by host`,`Counts hosts`],a:[1],
  e:`<b>dedup</b> removes duplicate events, keeping the <b>first</b> occurrence. <code>dedup 3 host</code> keeps up to 3 per host.`,d:SR+"Dedup"},
 {q:`Which sorts by <code>count</code> descending, and how do you bypass the default 10,000-result limit?`,
  o:[`<code>sort count</code>; use <code>sort max</code>`,`<code>sort -count</code>; use <code>sort 0 -count</code>`,`<code>sort +count</code>; use <code>sort all</code>`,`<code>sort desc count</code>; use <code>nolimit</code>`],a:[1],
  e:`<b><code>-</code> = descending</b>. <b><code>sort 0</code></b> removes the 10,000-result cap. A leading integer (e.g. <code>sort 5</code>) limits results.`,d:SR+"Sort"},
 {q:`What is the default number of events returned by <code>head</code> and <code>tail</code>?`,
  o:[`100`,`10`,`1000`,`50`],a:[1],
  e:`Both default to <b>10</b>. <code>head</code> = first N (centralized streaming); <code>tail</code> = last N.`,d:SR+"Head"},
 {q:`The <code>fillnull</code> command replaces null values with what, if <code>value=</code> is not specified?`,
  o:[`"null"`,`<code>0</code>`,`an empty string`,`"N/A"`],a:[1],
  e:`Default fill value is <b><code>0</code></b>. With no field named, it fills all fields; name fields to scope it.`,d:SR+"Fillnull"},
 {q:`Which command renames a field for the rest of the pipeline?`,
  o:[`<code>rename</code>`,`<code>replace</code>`,`<code>eval</code>`,`<code>fields</code>`],a:[0],
  e:`<b>rename</b> (e.g. <code>rename src AS source_ip</code>). After renaming, only the new name works downstream.`,d:SR+"Rename"},
 {q:`In <code>eval</code>, which operator concatenates strings?`,
  o:[`<code>+</code>`,`the dot <code>.</code>`,`<code>&</code>`,`<code>concat()</code> only`],a:[1],
  e:`Use the <b>dot <code>.</code></b>: <code>eval full=first." ".last</code>. In eval, <code>+</code> is arithmetic only.`,d:SR+"CommonEvalFunctions"},
 {q:`Which is TRUE about the <code>eval</code> <code>case()</code> function?`,
  o:[`It has a built-in default branch`,`It returns the first condition that is true; add a <code>1==1</code> branch for a default`,`It can only take two arguments`,`It replaces null values`],a:[1],
  e:`<b>case()</b> evaluates pairs and returns the first true one. There's <b>no default</b> - add <code>1==1,"default"</code>.`,d:SR+"CommonEvalFunctions"},
 {q:`Which command loops the same eval over multiple fields using the <code>&lt;&lt;FIELD&gt;&gt;</code> placeholder?`,
  o:[`<code>foreach</code>`,`<code>appendpipe</code>`,`<code>map</code>`,`<code>mvexpand</code>`],a:[0],
  e:`<b>foreach</b>: <code>foreach * [eval &lt;&lt;FIELD&gt;&gt;=round(&lt;&lt;FIELD&gt;&gt;,2)]</code> runs the eval on each field.`,d:SR+"Foreach"},

 // ---- Module 3: Correlating Events ----
 {q:`What does the <code>transaction</code> command do?`,
  o:[`Collapses events into a stats table`,`Groups related events into a single event and adds <code>duration</code> and <code>eventcount</code>`,`Filters by field value`,`Renames fields`],a:[1],
  e:`<b>transaction</b> bundles related events into one grouped event; adds <code>duration</code> + <code>eventcount</code>.`,d:SR+"Transaction"},
 {q:`When should you use <code>stats</code> instead of <code>transaction</code>?`,
  o:[`When you need the raw events kept together`,`When you only need aggregates/counts - stats is faster and more scalable`,`When you need startswith/endswith`,`Never`],a:[1],
  e:`Prefer <b>stats</b> for aggregation (faster, no memory limits). Use <b>transaction</b> only when you need the grouping itself or start/end logic.`,d:SR+"Transaction"},
 {q:`In <code>transaction</code>, what is the difference between <code>maxspan</code> and <code>maxpause</code>?`,
  o:[`They are the same`,`maxspan = max total duration of the transaction; maxpause = max gap allowed between consecutive events`,`maxspan = gap between events; maxpause = total length`,`Both set the number of events`],a:[1],
  e:`<b>maxspan</b> caps the whole transaction's length; <b>maxpause</b> caps the gap between adjacent events.`,d:SR+"Transaction"},
 {q:`How do <code>append</code> and <code>appendcols</code> differ?`,
  o:[`append adds columns; appendcols adds rows`,`append adds subsearch results as extra rows; appendcols attaches them as extra columns`,`They are identical`,`Both require transaction`],a:[1],
  e:`<b>append</b> = extra <b>rows</b>; <b>appendcols</b> = extra <b>columns</b> (side-by-side).`,d:SR+"Append"},
 {q:`Which command combines results from two datasets by matching on a common field, SQL-style?`,
  o:[`<code>join</code>`,`<code>appendpipe</code>`,`<code>dedup</code>`,`<code>bin</code>`],a:[0],
  e:`<b>join</b> matches on field(s), like a SQL join. Often <code>stats</code> is preferred for scale.`,d:SR+"Join"},
 {q:`A subsearch enclosed in square brackets <code>[ ... ]</code>:`,
  o:[`Runs last`,`Runs first and passes its results into the outer search`,`Cannot be used with search`,`Has no limits`],a:[1],
  e:`The <b>subsearch runs first</b>; its results become a filter fed into the outer search.`,d:SUB},
 {q:`What are the default limits on a subsearch?`,
  o:[`No limits`,`~10,000 results and a 60-second timeout`,`100 results and 10 seconds`,`1,000,000 results`],a:[1],
  e:`Subsearches default to <b>10,000 results</b> and a <b>60-second</b> timeout - prefer <code>stats</code> for large sets.`,d:SUB},

 // ---- Module 4: Creating & Managing Fields ----
 {q:`Which command extracts fields using a regex with <b>named capture groups</b> that you write yourself?`,
  o:[`<code>erex</code>`,`<code>rex</code>`,`<code>spath</code>`,`<code>fields</code>`],a:[1],
  e:`<b>rex</b> uses <code>(?&lt;name&gt;...)</code> named groups you write, e.g. <code>rex "user_id=(?&lt;user_id&gt;\\d+)"</code>.`,d:SR+"Rex"},
 {q:`Which command generates an extraction regex from <b>example values</b> you provide?`,
  o:[`<code>rex</code>`,`<code>erex</code>`,`<code>spath</code>`,`<code>eval</code>`],a:[1],
  e:`<b>erex</b> ("example rex") takes <code>examples=</code> and writes the regex for you.`,d:SR+"Erex"},
 {q:`At search time, which process automatically extracts fields (like <code>key=value</code> pairs) from raw data?`,
  o:[`the field extractor`,`the fields command`,`field discovery`,`a lookup`],a:[2],
  e:`<b>Field discovery</b> is the automatic search-time extraction. The Field Extractor is a GUI you invoke; <code>fields</code> trims existing fields.`,d:KN+"Aboutfields"},
 {q:`The Field Extractor (IFX) offers which two extraction methods?`,
  o:[`Regex and Delimiter`,`JSON and XML`,`Index-time and Frozen`,`GET and POST`],a:[0],
  e:`The <b>IFX</b> supports a <b>Regex</b> method (unstructured text) and a <b>Delimiter</b> method (CSV/TSV-like). It saves a knowledge object.`,d:KN+"Managesearch-timefieldextractions"},
 {q:`Which are default fields stamped on every event? <i>(Select all that apply.)</i>`,
  o:[`<code>host</code>`,`<code>source</code>`,`<code>sourcetype</code>`,`<code>username</code>`],a:[0,1,2],
  e:`<b>host</b>, <b>source</b>, <b>sourcetype</b> (plus <code>index</code>, <code>_time</code>, <code>_raw</code>). <code>username</code> is not a default field.`,d:KN+"Usedefaultfields"},
 {q:`Why does Splunk favor search-time field extraction over index-time?`,
  o:[`It is required for forwarders`,`It is flexible - editable anytime, applies to old data, and doesn't bloat the index`,`It is faster to index`,`It is the only option`],a:[1],
  e:`<b>Search-time</b> extractions can be changed anytime, apply to already-indexed data, and avoid index bloat. Index-time is baked in.`,d:KN+"Managesearch-timefieldextractions"},
 {q:`Which command parses <b>JSON/XML</b> by path?`,
  o:[`<code>spath</code>`,`<code>rex</code>`,`<code>erex</code>`,`<code>dedup</code>`],a:[0],
  e:`<b>spath</b> extracts from structured JSON/XML using paths (e.g. <code>spath path=user.name</code>).`,d:SR+"Spath"},
 {q:`What is the difference between <code>_time</code> and <code>_indextime</code>?`,
  o:[`They are the same`,`<code>_time</code> = when the event occurred; <code>_indextime</code> = when Splunk ingested it`,`<code>_time</code> = index time; <code>_indextime</code> = event time`,`<code>_indextime</code> is the user's timezone`],a:[1],
  e:`<b><code>_time</code></b> = event timestamp; <b><code>_indextime</code></b> = when it was indexed. Different moments.`,d:KN+"Usedefaultfields"},
 {q:`Which statement about the <code>index</code> field is TRUE?`,
  o:[`Index names are case-insensitive`,`The field name is case-insensitive but the index value is effectively case-sensitive`,`<code>index=Main</code> and <code>index=main</code> are always identical`,`index is not a default field`],a:[1],
  e:`Index <b>values</b> are case-sensitive (an exception to the usual rule) - <code>index=main</code> ≠ <code>index=Main</code>.`,d:KN+"Aboutfields"},

 // ---- Module 5: Field Aliases & Calculated Fields ----
 {q:`What does a field alias do?`,
  o:[`Deletes the original field`,`Gives an existing field an additional name (the original still works) - used to normalize sources`,`Computes a new value`,`Filters events`],a:[1],
  e:`A <b>field alias</b> adds an alternate name; the original remains. Key for normalizing sources to one standard name (CIM).`,d:KN+"Aboutfields"},
 {q:`A calculated field is essentially:`,
  o:[`A saved lookup`,`A saved <code>eval</code> expression that runs automatically at search time`,`A tag on a field=value`,`A macro`],a:[1],
  e:`A <b>calculated field</b> = a saved <code>eval</code> applied automatically (e.g. <code>EVAL-mb = bytes/1024/1024</code>).`,d:KN+"definecalcfields"},
 {q:`A calculated field may be based on which of the following?`,
  o:[`The output of a lookup`,`A field that already exists at search time (extracted field, alias, or another calculated field)`,`A raw keyword`,`The index name only`],a:[1],
  e:`Calculated fields run <b>before lookups</b>, so they can use extracted fields, aliases, and other calculated fields - but <b>not</b> lookup outputs.`,d:KN+"definecalcfields"},
 {q:`In the search-time sequence, when do calculated fields run relative to lookups?`,
  o:[`After lookups`,`Before lookups`,`At the same time`,`Never`],a:[1],
  e:`Order: extraction → aliases → <b>calculated fields</b> → <b>lookups</b> → event types → tags. That's why a calc field can't use lookup output.`,d:KN+"definecalcfields"},
 {q:`When are field aliases applied in the search-time order?`,
  o:[`After lookups`,`After field extraction, before calculated fields and lookups`,`Before field extraction`,`After tags`],a:[1],
  e:`<b>Aliases run after extraction but before calculated fields/lookups</b>, so a calculated field <i>can</i> reference an alias.`,d:KN+"Aboutfields"},

 // ---- Module 6: Tags & Event Types ----
 {q:`A tag is attached to a ___ and is ___.`,
  o:[`search string; case-insensitive`,`field=value pair; case-sensitive`,`sourcetype; numeric`,`index; time-bound`],a:[1],
  e:`A <b>tag</b> labels a specific <b>field=value pair</b> and is <b>case-sensitive</b>. Many-to-many.`,d:KN+"Abouttagsandaliases"},
 {q:`An event type is best described as:`,
  o:[`A saved search string (no time range) that classifies events matching it`,`A clickable action on a field`,`A moving average`,`A lookup table`],a:[0],
  e:`An <b>event type</b> is a saved search condition (no time range/pipes) that tags matching events with <code>eventtype=</code>.`,d:KN+"Abouteventtypes"},
 {q:`Which is TRUE about event type names?`,
  o:[`They may contain spaces`,`They cannot contain spaces; on multiple matches, priority decides ordering`,`They must be numeric`,`They are case-sensitive values`],a:[1],
  e:`Event type <b>names have no spaces</b>. When several match an event, <b>priority</b> (1 = highest) resolves order.`,d:KN+"Abouteventtypes"},
 {q:`What is the correct syntax to find events associated with a tag named <code>database</code> on the <code>host</code> field?`,
  o:[`<code>tag=database</code> or <code>tag::host=database</code>`,`<code>tagged(database)</code>`,`<code>eventtype=database</code>`,`<code>host.tag=database</code>`],a:[0],
  e:`Use <b><code>tag=database</code></b> (any field) or <b><code>tag::host=database</code></b> (scoped to the host field).`,d:KN+"Abouttagsandaliases"},
 {q:`What is the key difference between a tag and an event type?`,
  o:[`A tag classifies events matching a search; an event type labels a field=value`,`A tag labels a field=value; an event type classifies events matching a search`,`They are identical`,`Only event types are knowledge objects`],a:[1],
  e:`<b>Tag</b> = nickname for a field=value. <b>Event type</b> = classification of events matching a search. Event types can themselves be tagged.`,d:KN+"Abouteventtypes"},
 {q:`Does an event type include a time range?`,
  o:[`Yes, always`,`No - an event type is just the matching search logic, with no time range`,`Only in Fast mode`,`Only for accelerated models`],a:[1],
  e:`An <b>event type has no time range</b> (and no pipes) - it's only the classifying search terms.`,d:KN+"Abouteventtypes"},

 // ---- Module 7: Macros ----
 {q:`How do you invoke a search macro named <code>daily_errors</code> with no arguments?`,
  o:[`<code>"daily_errors"</code>`,`<code>&#96;daily_errors&#96;</code> (backticks)`,`<code>[daily_errors]</code>`,`<code>$daily_errors$</code>`],a:[1],
  e:`Macros are invoked with <b>backticks</b>. Quotes make a literal string; <code>$...$</code> is an argument placeholder inside a definition.`,d:KN+"Definesearchmacros"},
 {q:`For a macro that takes two arguments, how are the name and the arguments written?`,
  o:[`<code>mymacro</code>; refer to args as <code>%1 %2</code>`,`<code>mymacro(2)</code>; refer to args in the definition as <code>$arg1$</code>, <code>$arg2$</code>`,`<code>mymacro[2]</code>; args as <code>{1} {2}</code>`,`<code>mymacro</code>; args as <code>&amp;1 &amp;2</code>`],a:[1],
  e:`Append the arg count to the name (<b><code>mymacro(2)</code></b>) and reference args as <b><code>$arg1$</code>, <code>$arg2$</code></b> (dollar-delimited).`,d:KN+"Definesearchmacros"},
 {q:`Where are search macros defined in the UI?`,
  o:[`Settings → Advanced Search → Search macros`,`Settings → Indexes`,`Settings → Fields`,`Settings → Data models`],a:[0],
  e:`Macros live under <b>Settings → Advanced Search → Search macros</b> (stored in <code>macros.conf</code>).`,d:KN+"Definesearchmacros"},

 // ---- Module 8: Workflow Actions ----
 {q:`Which are valid workflow action types? <i>(Select all that apply.)</i>`,
  o:[`GET`,`POST`,`Search`,`PUT`],a:[0,1,2],
  e:`The three types are <b>GET</b> (open a URI), <b>POST</b> (submit to a URI), and <b>Search</b> (secondary search). No PUT.`,d:KN+"CreateworkflowactionsinSplunkWeb"},
 {q:`What is the difference between a GET and a POST workflow action?`,
  o:[`GET submits data; POST opens a link`,`GET opens a URI/link passing field values; POST sends an HTTP POST request with field-value arguments`,`They are identical`,`GET runs a search; POST opens a dashboard`],a:[1],
  e:`<b>GET</b> opens a link (data in the URL); <b>POST</b> submits data in the request body to a URI.`,d:KN+"CreateworkflowactionsinSplunkWeb"},
 {q:`What is a limitation of a Search workflow action?`,
  o:[`It cannot open a new window`,`It can only build its search from fields present in the event`,`It requires acceleration`,`It only works on the _internal index`],a:[1],
  e:`A <b>Search workflow action</b> can only use <b>fields available in the event</b> - not arbitrary/derived values.`,d:KN+"CreateworkflowactionsinSplunkWeb"},

 // ---- Module 9: Data Models & Pivot ----
 {q:`What must be included when using the <code>datamodel</code> command?`,
  o:[`Only a time range`,`The data model name (optionally a dataset/object name)`,`A lookup table`,`A regular expression`],a:[1],
  e:`<b><code>| datamodel &lt;model&gt; &lt;dataset&gt; search</code></b> - you must supply the data model name.`,d:KN+"Aboutdatamodels"},
 {q:`What is the main purpose of Pivot?`,
  o:[`To forward data`,`To let users build reports/visualizations from a data model without writing SPL`,`To accelerate indexing`,`To extract fields`],a:[1],
  e:`<b>Pivot</b> lets non-SPL users build tables/charts by pointing and clicking on a <b>data model</b>.`,d:PIV},
 {q:`Which command queries accelerated data models for fast results, and which dataset type can be accelerated?`,
  o:[`<code>datamodel</code>; root search`,`<code>tstats</code>; event-based (root event) datasets`,`<code>stats</code>; any dataset`,`<code>pivot</code>; root transaction only`],a:[1],
  e:`<b><code>tstats</code></b> runs against accelerated tsidx summaries. Root <b>event</b> datasets can be accelerated - as can root <b>search</b> datasets that use only streaming commands; transaction datasets and search datasets with transforming commands cannot be persistently accelerated.`,d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Acceleratedatamodels"},

 // ---- Module 10: CIM ----
 {q:`The Splunk Common Information Model (CIM) is a collection of what type of knowledge object?`,
  o:[`Macros`,`Data models`,`Lookups`,`Tags`],a:[1],
  e:`CIM is a set of predefined <b>data models</b> that normalize field names across sources.`,d:CIM},
 {q:`What does the CIM add-on do?`,
  o:[`Reindexes raw data into a new format`,`Normalizes field names/formats across different sources so one search works everywhere (e.g. <code>src</code>, <code>dest</code>, <code>user</code>)`,`Compresses indexes`,`Forwards data to indexers`],a:[1],
  e:`<b>CIM</b> maps equivalent fields to <b>consistent names</b> (via aliases/tags/eventtypes) - it does <b>not</b> reindex data.`,d:CIM},
 {q:`Which knowledge objects does CIM primarily use to normalize data to its models?`,
  o:[`Macros and lookups only`,`Field aliases, tags, and event types mapped to CIM data models`,`Workflow actions`,`Forwarders`],a:[1],
  e:`CIM normalization is driven by <b>field aliases, tags, and event types</b> mapped onto the CIM <b>data models</b>.`,d:CIM},

 // ---- extra mixed / high-yield ----
 {q:`Which eval function returns the first non-null value from a list of fields?`,
  o:[`<code>isnull()</code>`,`<code>coalesce()</code>`,`<code>fillnull()</code>`,`<code>tonumber()</code>`],a:[1],
  e:`<b>coalesce()</b> returns the first non-null value. <code>fillnull</code> is a command, not an eval function.`,d:SR+"CommonEvalFunctions"},
 {q:`What does <code>earliest=-7d@d</code> mean?`,
  o:[`7 days ago at the current time of day`,`7 days ago, snapped to midnight (start of day)`,`7 days in the future`,`the last 7 hours`],a:[1],
  e:`<code>-7d</code> = back 7 days; <b><code>@d</code> snaps to midnight</b> (start of day). <code>@</code> rounds down.`,d:SR+"SearchTimeModifiers"},
 {q:`How do <code>eventstats</code> and <code>streamstats</code> differ?`,
  o:[`eventstats = running total; streamstats = group aggregate`,`eventstats = group aggregate stamped on every event; streamstats = running/cumulative row-by-row`,`Both collapse rows into a table`,`Both are generating commands`],a:[1],
  e:`<b>eventstats</b> = whole-group aggregate on every event; <b>streamstats</b> = running/cumulative value per row. Neither collapses rows.`,d:SR+"Eventstats"},
 {q:`How does <code>appendpipe</code> differ from <code>append</code>?`,
  o:[`appendpipe runs a separate search`,`appendpipe runs a sub-pipeline on the current results and appends the output (e.g. a totals row)`,`appendpipe adds columns`,`appendpipe is generating`],a:[1],
  e:`<b>appendpipe</b> reuses the results you already have (no new search); great for a TOTAL row. <b>append</b> runs a separate search.`,d:SR+"Appendpipe"},
 {q:`What do <code>xyseries</code> and <code>untable</code> do?`,
  o:[`Filter events`,`<code>xyseries</code> reshapes rows into a matrix (long→wide); <code>untable</code> reshapes a table back into rows (wide→long)`,`They are eval functions`,`<code>untable</code> builds a chart`],a:[1],
  e:`<b>xyseries</b> = rows→matrix; <b>untable</b> = matrix→rows (the inverse).`,d:SR+"Xyseries"},
 {q:`The <code>search</code> command at the very start of a search is:`,
  o:[`Required to be typed explicitly`,`Implicit (automatically applied)`,`A transforming command`,`Only for lookups`],a:[1],
  e:`The leading <b><code>search</code> is implicit</b> - you don't type it; Splunk applies it to the first set of terms.`,d:SR+"Search"},
 {q:`Which command reads and displays the contents of a lookup table itself?`,
  o:[`<code>lookup</code>`,`<code>inputlookup</code>`,`<code>outputlookup</code>`,`<code>fields</code>`],a:[1],
  e:`<b>inputlookup</b> is a generating command that reads a lookup table (<code>| inputlookup mytable.csv</code>). <code>lookup</code> enriches events; <code>outputlookup</code> writes results out.`,d:SR+"Inputlookup"},
 {q:`Which command generates placeholder/test results with no data source?`,
  o:[`<code>makeresults</code>`,`<code>gentimes</code> only`,`<code>eval</code>`,`<code>stats</code>`],a:[0],
  e:`<b>| makeresults</b> creates test rows (e.g. <code>| makeresults count=1</code>) - a generating command useful for testing eval.`,d:SR+"Makeresults"},

 // ---- Challenge questions (harder, official-doc grounded) ----
 {q:`In a <code>lookup</code>, what is the difference between <code>OUTPUT</code> and <code>OUTPUTNEW</code>?`,
  o:[`<code>OUTPUT</code> only writes fields that don't exist; <code>OUTPUTNEW</code> overwrites`,`<code>OUTPUT</code> overwrites existing fields; <code>OUTPUTNEW</code> only writes a field if it isn't already present`,`They are identical`,`<code>OUTPUT</code> is for CSV, <code>OUTPUTNEW</code> for KV Store`],a:[1],
  e:`<b>OUTPUT</b> overwrites (clobbers) any existing field with the lookup value; <b>OUTPUTNEW</b> only adds the field when it is <i>not already present</i> on the event.`,d:SR+"Lookup",cat:'fields',hard:true},
 {q:`Which command creates a <b>separate event for each value</b> of a multivalue field?`,
  o:[`<code>makemv</code>`,`<code>mvexpand</code>`,`<code>mvcombine</code>`,`<code>nomv</code>`],a:[1],
  e:`<b>mvexpand</b> expands each value into its own event. <code>makemv</code> splits a field into multivalue; <code>nomv</code> collapses MV to single-value; <code>mvcombine</code> groups values together.`,d:SR+"Mvexpand",cat:'filter',hard:true},
 {q:`You want to <b>display</b> bytes as a human-readable string but still <b>sort numerically</b>. Which command?`,
  o:[`<code>eval</code>`,`<code>fieldformat</code>`,`<code>rename</code>`,`<code>tostring</code>`],a:[1],
  e:`<b>fieldformat</b> changes only the <i>display</i> of a field while keeping the underlying value intact - so sorting and calculations still use the real number. <code>eval</code> would overwrite the value with a string.`,d:SR+"Fieldformat",cat:'filter',hard:true},
 {q:`When <code>transaction</code> discards (evicts) a group that exceeds its limits, how is that transaction identified?`,
  o:[`With <code>closed_txn=0</code>`,`With <code>duration=-1</code>`,`It is deleted silently`,`With <code>eventcount=0</code>`],a:[0],
  e:`Evicted/incomplete transactions are marked <b><code>closed_txn=0</code></b> (a complete one is <code>closed_txn=1</code>). Eviction happens when <code>maxevents</code>/<code>maxspan</code>/<code>maxpause</code>/memory limits are hit.`,d:SR+"Transaction",cat:'correlate',hard:true},
 {q:`In a <code>tstats</code> search on an accelerated data model, what does <code>summariesonly=true</code> do?`,
  o:[`Returns only results from the accelerated tsidx summaries, ignoring un-summarized raw data`,`Forces a real-time search`,`Disables acceleration`,`Returns only summary-index data`],a:[0],
  e:`<b><code>summariesonly=true</code></b> restricts <code>tstats</code> to the accelerated <b>tsidx summaries</b> (fast, but excludes data not yet summarized). <code>summariesonly=false</code> also scans raw data to fill gaps.`,d:SR+"Tstats",cat:'datamodels',hard:true},
 {q:`Which command adds <b>only a summary row</b> of column totals at the bottom (not per-row totals)?`,
  o:[`<code>addtotals</code>`,`<code>addcoltotals</code>`,`<code>addrowtotals</code>`,`<code>stats</code>`],a:[1],
  e:`<b>addcoltotals</b> adds a single row summing each numeric column. <code>addtotals</code> (default <code>row=t</code>) adds a per-row <i>total column</i>; <code>addtotals col=t</code> adds a totals row.`,d:SR+"Addcoltotals",cat:'viz',hard:true},
 {q:`Which command replaces null values with the <b>last non-null value</b> seen for that field?`,
  o:[`<code>fillnull</code>`,`<code>filldown</code>`,`<code>coalesce</code>`,`<code>fillmv</code>`],a:[1],
  e:`<b>filldown</b> carries the most recent non-null value forward into nulls. <code>fillnull</code> replaces nulls with a fixed value (default <code>0</code>).`,d:SR+"Filldown",cat:'filter',hard:true},
 {q:`What is a macro <b>validation expression</b> used for?`,
  o:[`To define the macro's arguments`,`To check argument values before the macro runs and return an error if invalid`,`To schedule the macro`,`To share the macro globally`],a:[1],
  e:`A <b>validation expression</b> is an eval expression that checks the argument(s); if it evaluates to false (or returns a string), Splunk shows a validation error instead of running the macro.`,d:KN+"Definesearchmacros",cat:'macros',hard:true},
 {q:`Which eval function returns the <b>number of values</b> in a multivalue field?`,
  o:[`<code>mvindex()</code>`,`<code>mvcount()</code>`,`<code>mvjoin()</code>`,`<code>len()</code>`],a:[1],
  e:`<b>mvcount(field)</b> returns how many values the field has (null if it doesn't exist). <code>mvindex()</code> picks a value by position; <code>mvjoin()</code> concatenates; <code>len()</code> is string length.`,d:SR+"MultivalueEvalFunctions",cat:'filter',hard:true},
 {q:`What is the correct <b>search-time</b> processing order?`,
  o:[`aliases → extractions → calculated fields → lookups`,`field extractions → field aliases → calculated fields → lookups → event types → tags`,`lookups → calculated fields → aliases → extractions`,`tags → event types → lookups → calculated fields`],a:[1],
  e:`Order: <b>field extraction → field aliases → calculated fields (eval) → lookups → event types → tags</b>. Each step can only use fields produced by earlier steps.`,d:KN+"Managesearch-timefieldextractions",cat:'fields',hard:true},
 {q:`In a workflow action, how do you insert the <b>value of a field</b> from the selected event?`,
  o:[`<code>%field%</code>`,`<code>$field$</code>`,`<code>{{field}}</code>`,`<code>@field</code>`],a:[1],
  e:`Field values are inserted with <b><code>$fieldname$</code></b> tokens (e.g. a GET URL like <code>...?ip=$src_ip$</code>). Special tokens <code>$@field_name$</code>/<code>$@field_value$</code> reference the clicked field.`,d:KN+"CreateworkflowactionsinSplunkWeb",cat:'workflow',hard:true},
 {q:`Which command merges results from multiple datasets and is generally more efficient than <code>append</code> for combining searches?`,
  o:[`<code>appendcols</code>`,`<code>union</code>`,`<code>join</code>`,`<code>appendpipe</code>`],a:[1],
  e:`<b>union</b> combines events from multiple searches/datasets and can be more efficient than <code>append</code> (which tacks a subsearch onto the end, subject to subsearch limits).`,d:SR+"Union",cat:'correlate',hard:true},
 {q:"A visualization such as a column or pie chart cannot be built directly from raw events. Which of the following are transforming commands whose output can be rendered as a visualization? (Choose all that apply.)", o:["<code>stats</code>","<code>table</code>","<code>timechart</code>","<code>eval</code>"], a:[0,2], e:"Transforming commands order results into a data table of rows and columns that the Visualization tab can plot. <code>stats</code>, <code>chart</code>, <code>timechart</code>, <code>top</code>, and <code>rare</code> are transforming commands. <code>table</code> only formats fields into a list and <code>eval</code> calculates a field per event; neither aggregates results, so neither is a transforming command and raw-event output stays on the Statistics/Events tab rather than a chart.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Stats", cat:"viz"},
 {q:"Consider the search <code>index=web | chart count over host by status</code>. What role do the <b>over</b> and <b>by</b> clauses play?", o:["<code>over host</code> sets the x-axis field and <code>by status</code> splits the results into a separate data series (column) per status value","<code>over host</code> filters to a single host and <code>by status</code> sorts the output","<code>over host</code> creates the series and <code>by status</code> sets the x-axis","Both clauses are optional aliases for the same thing and can be swapped with no change to the result"], a:[0], e:"With <code>chart</code>, the field named after <code>over</code> becomes the x-axis (the row-defining field), and the field named after <code>by</code> becomes the split-by field, producing one data series/column per distinct value of that field. Swapping them changes the shape of the table. Only <code>chart</code> uses <code>over</code>; <code>stats</code> uses <code>by</code> only.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Chart", cat:"viz"},
 {q:"Which statement about the <code>timechart</code> command is TRUE?", o:["The x-axis of a timechart is always <code>_time</code>, and the <code>span</code> argument controls the size of each time bucket","<code>timechart</code> lets you choose any field for the x-axis using an <code>over</code> clause","<code>timechart</code> cannot be used to build a visualization; it only produces raw events","<code>timechart</code> requires a <code>bin</code> command to appear before it or it will error"], a:[0], e:"<code>timechart</code> always plots time on the x-axis (<code>_time</code>), so it does not accept an <code>over</code> clause; the split field goes after <code>by</code>. The <code>span</code> argument (for example <code>span=1h</code>) sets the bucket size. It is a transforming command and buckets time automatically, so no separate <code>bin</code> is needed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Timechart", cat:"viz"},
 {q:"By default, the <code>top</code> command returns the 10 most common values of a field. Which two fields does it add to the results?", o:["<code>count</code> and <code>percent</code>","<code>count</code> and <code>total</code>","<code>value</code> and <code>frequency</code>","<code>sum</code> and <code>percent</code>"], a:[0], e:"<code>top</code> (and its opposite <code>rare</code>) adds a <code>count</code> field with the number of occurrences and a <code>percent</code> field with the percentage of the total that each value represents. The default <code>limit</code> is 10, and it can be changed with the <code>limit</code> argument (<code>limit=0</code> returns all).", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Top", cat:"viz"},
 {q:"When a <code>chart ... by &lt;field&gt;</code> search produces more distinct values than can be shown, some are grouped into an \"OTHER\" series. Which arguments control the number of distinct series shown and whether the leftover values are grouped into \"OTHER\"? (Choose all that apply.)", o:["<code>limit</code>","<code>useother</code>","<code>usenull</code>","<code>span</code>"], a:[0,1], e:"<code>limit</code> sets the maximum number of distinct series to display (default 10 for the split-by field). <code>useother</code> (default true) toggles whether values beyond the limit are collapsed into a single \"OTHER\" series. <code>usenull</code> instead controls the separate \"NULL\" series for events missing the field, and <code>span</code> sets numeric/time bucket size, so neither affects the OTHER grouping.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Chart", cat:"viz"},
 {q:"Splunk supports seven core chart types. Which chart type plots three numeric dimensions per marker, using the marker's <b>size</b> to represent the third value?", o:["Scatter chart","Bubble chart","Area chart","Pie chart"], a:[1], e:"A scatter chart is a 2-D plot showing the relationship between two numeric fields (x and y). A bubble chart is 3-D: it adds a third numeric dimension encoded as the size (area) of each bubble. Line, area, column, bar, and pie are the other standard chart types.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Chart", cat:"viz"},
 {q:"You run <code>... | stats sum(bytes) AS bytes BY host</code> and then want a single summary event at the bottom of the table that adds up the <code>bytes</code> column across all hosts. Which command and argument produce that column-totals (summary) row?", o:["<code>addtotals col=t</code>","<code>addtotals row=t</code>","<code>addtotals</code> with no arguments","<code>addtotals fieldname=Total</code>"], a:[0], e:"For <code>addtotals</code>, <code>col=t</code> (default is <code>col=false</code>) adds a summary event at the bottom that totals each field down its column. <code>row=t</code> is the default and instead adds a per-row <code>Total</code> field summing across columns. So <code>addtotals</code> with no arguments (or with only <code>fieldname</code>) gives a per-row total, not a bottom summary row.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Addtotals", cat:"viz"},
 {q:"How does <code>addcoltotals</code> differ from the default behavior of <code>addtotals</code>?", o:["<code>addcoltotals</code> adds only a summary row of column totals, while default <code>addtotals</code> (<code>row=true</code>) adds a per-row Total field across columns","<code>addcoltotals</code> adds a per-row total, while <code>addtotals</code> adds a summary row","They are identical aliases and always produce the same output","<code>addcoltotals</code> can only be used before a transforming command"], a:[0], e:"<code>addcoltotals</code> computes the sum of each numeric field and appends a single summary event (a column-totals row) - equivalent to <code>addtotals col=t row=f</code>. Default <code>addtotals</code> uses <code>row=true</code>, adding a <code>Total</code> field to each row summing across the specified fields. They are not identical.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Addcoltotals", cat:"viz"},
 {q:"The <code>iplocation</code> command enriches events by looking up an IP address. Which fields can it add to matching events? (Choose all that apply.)", o:["<code>City</code>","<code>Country</code>","<code>Region</code>","<code>ResponseTime</code>"], a:[0,1,2], e:"<code>iplocation</code> adds geographic fields derived from the IP address, including <code>City</code>, <code>Country</code>, <code>Region</code>, and <code>lat</code>/<code>lon</code> (and, with <code>allfields=true</code>, more such as <code>Continent</code> and <code>MetroCode</code>). The <code>lat</code> and <code>lon</code> fields it produces are what commands like <code>geostats</code> need. <code>ResponseTime</code> is not an <code>iplocation</code> output.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Iplocation", cat:"viz"},
 {q:"Which statement about the <code>geostats</code> command is TRUE?", o:["It aggregates data by geographic location using <code>lat</code> and <code>lon</code> fields, and <code>globallimit</code>/<code>locallimit</code> control how many result categories are shown","It renders a choropleth map by shading predefined region polygons","It requires only a Country name field and generates latitude and longitude automatically","It plots time on the x-axis, similar to <code>timechart</code>"], a:[0], e:"<code>geostats</code> clusters events into geographic bins for a cluster-map (marker) visualization and needs latitude/longitude fields (commonly produced by <code>iplocation</code>). <code>globallimit</code> caps the number of series across the whole map and <code>locallimit</code> caps series per cluster. Choropleth shading of predefined regions is done by <code>geom</code>, not <code>geostats</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Geostats", cat:"viz"},
 {q:"You want a choropleth (filled-region) map that shades U.S. states by a metric. Which command adds the geometric polygon data for those predefined regions to your results?", o:["<code>geom</code>","<code>geostats</code>","<code>iplocation</code>","<code>xyseries</code>"], a:[0], e:"<code>geom</code> adds geographic polygon (geometry) data from a featureCollection to your results so the Choropleth map visualization can shade predefined regions such as states or countries. <code>geostats</code> produces point/cluster markers, and <code>iplocation</code> only adds location fields from an IP.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Geom", cat:"viz"},
 {q:"A results table has one row per <code>host</code> with a <code>_time</code>-like matrix layout, but you need it converted from that \"matrix\" (columns per series) format back into a long list of rows with one row per name/value pair. Which command performs this matrix-to-rows transformation?", o:["<code>untable</code>","<code>xyseries</code>","<code>transpose</code>","<code>mvexpand</code>"], a:[0], e:"<code>untable</code> converts results from a tabular (matrix) format into a long, three-column list of rows: the x-axis field, a series-name column, and a value column. It is the inverse of <code>xyseries</code>, which takes row-based x/series/value data and reshapes it into a matrix (a chart-ready table).", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Untable", cat:"viz"},
 {q:"The <code>sparkline()</code> function embeds a tiny inline trend chart inside a results cell. Which commands can it be used with? (Choose all that apply.)", o:["<code>stats</code>","<code>chart</code>","<code>timechart</code>","<code>rare</code>"], a:[0,1], e:"<code>sparkline()</code> is a function available only inside the <code>stats</code> and <code>chart</code> commands, for example <code>stats sparkline(count) count BY host</code>. It is not a function of <code>timechart</code> or <code>rare</code>. The sparkline appears as a small inline chart in each row of the results table.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Stats", cat:"viz"},
 {q:"Which search correctly overlays a 5-point simple moving average on a count-over-time chart using the <code>trendline</code> command?", o:["<code>... | timechart count | trendline sma5(count) AS trend</code>","<code>... | timechart count | trendline avg5(count) AS trend</code>","<code>... | timechart count | trendline count sma5</code>","<code>... | timechart count | trendline type=sma period=5 field=count</code>"], a:[0], e:"<code>trendline</code> syntax is <code>&lt;trendtype&gt;&lt;period&gt;(&lt;field&gt;) [AS &lt;newfield&gt;]</code>. Valid trend types are <code>sma</code> (simple), <code>ema</code> (exponential), and <code>wma</code> (weighted) moving averages, and the period is an integer from 2 to 10000. So <code>sma5(count)</code> is correct; <code>avg</code> is not a valid trend type, and the other forms do not match the required syntax.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Trendline", cat:"viz"},
 {q:"Which statements correctly describe the difference between the <code>search</code> and <code>where</code> commands? (Choose all that apply.)", o:["<code>search</code> string matches are case-insensitive, while <code>where</code> comparisons are case-sensitive","<code>where</code> evaluates eval expressions and can compare one field to another field","<code>search</code> can compare two fields directly, such as <code>search bytes_in > bytes_out</code>","In <code>where</code>, a value in double quotes is treated as a literal string, not a field name"], a:[0,1,3], e:"<code>search</code> is case-insensitive; <code>where</code> is case-sensitive and uses eval-style expressions, so it can compare field-to-field (for example <code>| where bytes_in > bytes_out</code>). In <code>where</code>, double quotes mean a literal value while unquoted or single-quoted text is a field name. Basic <code>search</code> cannot compare one field to another field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Where", cat:"filter"},
 {q:"In the <code>where</code> command, which expression correctly filters events where the <b>status</b> field equals the value stored in the <b>expected_status</b> field?", o:["| where status = \"expected_status\"","| where status = expected_status","| where status = 'expected_status'","| where status == \"expected_status\""], a:[1], e:"In <code>where</code>, unquoted text (or single quotes) refers to a field name, so <code>status = expected_status</code> compares the two fields. Double quotes such as <code>\"expected_status\"</code> would compare <b>status</b> to the literal string. The comparison operator in eval/where is a single <code>=</code> (or <code>==</code>), but <code>== \"expected_status\"</code> still uses a literal string, not the field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Where", cat:"filter"},
 {q:"You want to use <code>where</code> to keep only events where the <b>host</b> field begins with <code>web</code> followed by any characters. Which is the correct syntax?", o:["| where host like \"web%\"","| where host = \"web*\"","| where like(host, \"web*\")","| where match(host, \"web%\")"], a:[0], e:"The <code>where</code> command performs wildcard matching with the <code>like()</code> function (or the <code>LIKE</code> operator). In <code>like()</code>, <code>%</code> matches multiple characters and <code>_</code> matches a single character. The asterisk <code>*</code> is not the wildcard for <code>like()</code>; <code>match()</code> uses regular expressions, not <code>%</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Where", cat:"filter"},
 {q:"Which statements about the <code>fields</code> command are true? (Choose all that apply.)", o:["<code>fields + status uri</code> keeps only the listed fields (plus internal fields)","<code>fields - status uri</code> removes the listed fields from the results","Removing unneeded fields early with <code>fields</code> can improve search performance","<code>fields</code> is a transforming command that aggregates events into a table"], a:[0,1,2], e:"<code>fields +</code> keeps only the named fields, <code>fields -</code> removes them, and limiting fields early reduces the data carried through the pipeline, improving performance. <code>fields</code> is not a transforming command and does not aggregate; it simply includes or excludes fields.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Fields", cat:"filter"},
 {q:"Which statement best describes the difference between the <code>table</code> and <code>fields</code> commands?", o:["<code>table</code> is used to format results for display and does not aggregate, while <code>fields</code> includes or excludes fields from the pipeline","<code>table</code> is a transforming command that aggregates data, while <code>fields</code> only renames fields","<code>table</code> can only be used with the <code>-</code> operator, while <code>fields</code> uses <code>+</code>","<code>table</code> improves performance more than <code>fields</code> because it drops <code>_raw</code> internally"], a:[0], e:"<code>table</code> specifies the fields and column order for display but is not a transforming command and performs no aggregation. <code>fields</code> includes (<code>+</code>) or excludes (<code>-</code>) fields in the pipeline and is generally better for performance because it can be applied early; <code>table</code> retains underlying data.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Table", cat:"filter"},
 {q:"Given the search <code>... | dedup 2 host</code>, what is the result?", o:["Keeps the first 2 events for each unique value of <b>host</b>","Keeps only events where <b>host</b> appears at least 2 times","Keeps the last 2 events for each unique value of <b>host</b>","Removes the first 2 duplicate events overall"], a:[0], e:"<code>dedup N field</code> keeps the first N events for each unique combination of the specified field values. By default (<code>dedup host</code>) it keeps only the first event per value; adding <code>2</code> keeps the first two per <b>host</b>. It keeps the first occurrences, not the last.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Dedup", cat:"filter"},
 {q:"A search ends with <code>... | sort 0 - bytes</code>. Which statement correctly describes the result?", o:["Results are sorted by <b>bytes</b> in descending order with the default 10,000-event sort limit removed","Results are sorted by <b>bytes</b> in ascending order and limited to the first event","Only the 0 highest <b>bytes</b> values are returned, effectively returning nothing","Results are sorted by <b>bytes</b> ascending with a hard cap of 10,000 events"], a:[0], e:"A leading <code>-</code> sorts descending (a <code>+</code> would sort ascending). The leading <code>0</code> is a count that removes the default 10,000-event limit on how many events <code>sort</code> will process, so all events are sorted. A positive number like <code>sort 5</code> would instead limit output to that many events.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Sort", cat:"filter"},
 {q:"A search ends with <code>... | head</code> and no arguments. How many events are returned?", o:["The first 10 events","All events","The last 10 events","The first 1 event"], a:[0], e:"With no numeric argument, both <code>head</code> and <code>tail</code> default to 10 events. <code>head</code> returns the first 10 (from the beginning of the result set); <code>tail</code> returns the last 10.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Head", cat:"filter"},
 {q:"What is the difference between the <code>fillnull</code> and <code>filldown</code> commands?", o:["<code>fillnull</code> replaces null values with a specified value (0 by default), while <code>filldown</code> replaces nulls with the last non-null value seen","<code>fillnull</code> replaces nulls with the previous value, while <code>filldown</code> replaces them with 0","Both replace null values with 0, but <code>filldown</code> only works on numeric fields","<code>fillnull</code> removes events containing nulls, while <code>filldown</code> keeps them"], a:[0], e:"<code>fillnull</code> substitutes a fixed value for null fields, defaulting to <code>0</code> (a custom value can be set with <code>value=</code>). <code>filldown</code> instead carries forward the last non-null value for a field; if no previous value exists it uses an empty string.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Fillnull", cat:"filter"},
 {q:"Which <code>eval</code> expression correctly builds a full name by joining the <b>first</b> and <b>last</b> fields with a space?", o:["| eval name = first . \" \" . last","| eval name = first + \" \" + last","| eval name = concat(first, \" \", last)","| eval name = first & \" \" & last"], a:[0], e:"In <code>eval</code>, string concatenation uses the period <code>.</code> operator, so <code>first . \" \" . last</code> joins the values. The <code>+</code> operator performs arithmetic (and would fail or produce nulls on strings). There is no <code>concat()</code> or <code>&</code> operator in Splunk eval.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Eval", cat:"filter"},
 {q:"Which statements about the <code>eval</code> functions <code>case()</code>, <code>coalesce()</code>, and <code>in()</code> are correct? (Choose all that apply.)", o:["<code>case()</code> has no built-in default, so a final <code>1==1, \"default\"</code> condition is a common way to add one","<code>coalesce()</code> returns the first non-null value from its arguments","The <code>in()</code> function in eval must be nested inside another function such as <code>if()</code>","<code>case()</code> automatically returns \"OTHER\" for any value not matched"], a:[0,1,2], e:"<code>case()</code> returns the value for the first true condition and has no automatic default, so authors add <code>1==1</code> as a catch-all. <code>coalesce()</code> returns the first non-null argument. In eval, <code>in()</code> is not standalone; it must be wrapped in a function like <code>if(in(field, ...), ...)</code>. <code>case()</code> does not supply a default value on its own.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/CommonEvalFunctions", cat:"filter"},
 {q:"A field <b>tags</b> is multivalue containing <code>alpha</code>, <code>beta</code>, and <code>gamma</code>. Which pairing of eval multivalue function and result is correct?", o:["<code>mvcount(tags)</code> returns 3","<code>mvindex(tags, 0)</code> returns <code>gamma</code>","<code>mvjoin(tags, \"-\")</code> returns a multivalue field with 3 values","<code>mvcount(tags)</code> returns the concatenated string <code>alphabetagamma</code>"], a:[0], e:"<code>mvcount()</code> returns the number of values (3). <code>mvindex()</code> is zero-based, so <code>mvindex(tags, 0)</code> returns <code>alpha</code>, not <code>gamma</code>. <code>mvjoin(tags, \"-\")</code> collapses the values into a single string <code>alpha-beta-gamma</code>, not a multivalue field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/MultivalueEvalFunctions", cat:"filter"},
 {q:"What does the <code>mvexpand</code> command do to a multivalue field?", o:["Creates a separate event for each value in the multivalue field, copying the other fields","Counts the number of values and stores the count in a new field","Joins the values into a single delimited string within the same event","Removes duplicate values so the field becomes single-valued"], a:[0], e:"<code>mvexpand</code> expands a multivalue field so that each value becomes its own event, with the remaining fields duplicated across the new events. Counting is done by <code>mvcount()</code>, joining by <code>mvjoin()</code>, and deduplicating values by <code>mvdedup()</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Mvexpand", cat:"filter"},
 {q:"Which statement correctly contrasts <code>fieldformat</code> with using <code>eval</code> to format a value, and <code>eventstats</code> with <code>streamstats</code>? (Choose all that apply.)", o:["<code>fieldformat</code> changes only how a value is displayed while preserving the original value for sorting and calculations","Using <code>eval</code> to reformat a field changes the underlying value, which can affect later sorting","<code>eventstats</code> adds aggregate results to all events without removing them, while <code>streamstats</code> produces running (cumulative) values","<code>streamstats</code> and <code>eventstats</code> both remove the original events, returning only summary rows like <code>stats</code>"], a:[0,1,2], e:"<code>fieldformat</code> alters the displayed form but keeps the raw, sortable value; <code>eval</code> overwrites the actual value, which can change sort order. <code>eventstats</code> appends aggregate values to every event, and <code>streamstats</code> computes running statistics as events stream. Neither removes the events the way <code>stats</code> does.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Fieldformat", cat:"filter"},
 {q:"Which two fields does the <code>transaction</code> command automatically add to each transaction it creates?", o:["<code>span</code> and <code>count</code>","<code>duration</code> and <code>eventcount</code>","<code>closed_txn</code> and <code>_time</code>","<code>linecount</code> and <code>_raw</code>"], a:[1], e:"The <code>transaction</code> command adds two fields: <code>duration</code> (the difference between the timestamps of the first and last events in the transaction) and <code>eventcount</code> (the number of events in the transaction).", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"What does the <code>duration</code> field of a transaction represent?", o:["The number of events grouped into the transaction","The time between the first and last events in the transaction","The maximum pause allowed between consecutive events","The total time the search took to run"], a:[1], e:"<code>duration</code> is the difference between the timestamps of the earliest (first) and latest (last) events in the transaction. The count of events is stored separately in <code>eventcount</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"A transaction has <code>closed_txn=0</code>. What does this indicate?", o:["The transaction is complete and satisfied its constraints","The transaction is incomplete or was evicted (not closed)","The transaction contains exactly zero events","The transaction spanned zero seconds"], a:[1], e:"<code>closed_txn</code> is set to 1 (true) for complete/closed transactions and 0 (false) for evicted or incomplete transactions. A value of 0 means the transaction did not satisfy a closing condition (such as <code>maxevents</code>, <code>maxspan</code>, <code>maxpause</code>, or <code>startswith</code>) or was evicted due to memory limits.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"By default, what is the maximum number of events the <code>transaction</code> command will include in a single transaction?", o:["100","1000","10000","Unlimited"], a:[1], e:"The <code>maxevents</code> option defaults to 1000, so by default a transaction contains at most 1000 events. Setting <code>maxevents</code> to a negative value deactivates the constraint (no limit).", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"Given the search <code>sourcetype=access_combined | transaction JSESSIONID</code>, what does it do?", o:["Groups the access_combined events into transactions where all events share the same <code>JSESSIONID</code> value","Returns only the events whose <code>JSESSIONID</code> field is null","Counts how many distinct <code>JSESSIONID</code> values exist","Joins the access_combined events to another index on <code>JSESSIONID</code>"], a:[0], e:"<code>transaction JSESSIONID</code> groups events that share the same <code>JSESSIONID</code> value into single transactions (subject to any span/pause/event constraints). All events in a resulting transaction have that field value in common.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"Which statements about choosing between <code>transaction</code> and <code>stats</code> are true? (Choose all that apply.)", o:["<code>stats</code> is generally faster and more efficient, and is preferred in large distributed environments","<code>transaction</code> is useful when you must keep the raw events of each group together","<code>transaction</code> is preferred when grouping must be based on a start, end, or segment of the events","<code>stats</code> can group events using <code>startswith</code> and <code>endswith</code> conditions just like <code>transaction</code>"], a:[0,1,2], e:"<code>stats</code> is more efficient and scales better, so it is preferred when possible. Use <code>transaction</code> when you need the events themselves kept together, or when grouping depends on start/end/segment conditions. <code>stats</code> does not support <code>startswith</code>/<code>endswith</code>; those belong to <code>transaction</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"What is the difference between <code>append</code> and <code>appendcols</code>?", o:["<code>append</code> adds the subsearch results as new rows; <code>appendcols</code> adds them as new columns to existing rows","<code>append</code> adds new columns; <code>appendcols</code> adds new rows","Both add rows, but <code>appendcols</code> also sorts by <code>_time</code>","<code>append</code> runs before the main search; <code>appendcols</code> runs after"], a:[0], e:"<code>append</code> appends the results of a subsearch as additional rows at the bottom of the current results. <code>appendcols</code> appends the subsearch results as new columns (fields) to the existing rows, position by position.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Appendcols", cat:"correlate"},
 {q:"Which command performs a SQL-style join, matching rows from a subsearch to the main results on one or more shared fields?", o:["<code>append</code>","<code>union</code>","<code>join</code>","<code>transaction</code>"], a:[2], e:"<code>join</code> combines the results of a subsearch with the main search by matching on one or more fields, similar to a SQL join. <code>append</code> and <code>union</code> combine result sets without field-based matching.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Join", cat:"correlate"},
 {q:"Which statements about subsearches are correct? (Choose all that apply.)", o:["A subsearch is enclosed in square brackets and runs first, before the outer search","By default a subsearch returns a maximum of 10,000 results","By default a subsearch has a maximum runtime of 60 seconds","The outer search always runs first and passes its results into the subsearch"], a:[0,1,2], e:"A subsearch is enclosed in square brackets and is processed first; its output is then used by the outer search. By default it is limited to 10,000 results and a 60-second runtime, after which it is automatically finalized. The last option reverses the actual execution order.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Search/Aboutsubsearches", cat:"correlate"},
 {q:"You need to combine events from two separate searches into one result set as efficiently as possible for further processing. Which command is designed for combining datasets efficiently?", o:["<code>join</code>","<code>union</code>","<code>appendcols</code>","<code>transaction</code>"], a:[1], e:"<code>union</code> combines the results of two or more datasets (searches) into a single result set and is designed to do so efficiently. <code>join</code> matches on fields, and <code>appendcols</code> merges columns rather than combining datasets.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Union", cat:"correlate"},
 {q:"In the search <code>sourcetype=access_* | transaction clientip startswith=\"addtocart\" endswith=\"purchase\"</code>, what defines the boundaries of each transaction?", o:["Each transaction begins with an event matching \"addtocart\" and ends with an event matching \"purchase\"","Each transaction includes only events that contain both \"addtocart\" and \"purchase\"","The transaction is limited to a 1-minute window regardless of the events","Only events where <code>clientip</code> is missing are grouped"], a:[0], e:"<code>startswith</code> marks the event that begins a transaction and <code>endswith</code> marks the event that ends it. Here a transaction for a given <code>clientip</code> starts at an \"addtocart\" event and closes at a \"purchase\" event.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"Which of the following are valid ways to specify conditions for <code>startswith</code> or <code>endswith</code> in a <code>transaction</code>? (Choose all that apply.)", o:["A quoted search string, for example <code>startswith=\"login\"</code>","An <code>eval</code> filtering expression, for example <code>endswith=eval(status=200)</code>","A <code>searchmatch</code> expression matching the raw event","A required <code>stats</code> function, for example <code>startswith=count(user)</code>"], a:[0,1,2], e:"<code>startswith</code> and <code>endswith</code> accept a search/eval filtering expression. You can supply a quoted search string, an <code>eval(...)</code> expression, or use <code>searchmatch(...)</code> to match against the raw event. A <code>stats</code> aggregation function is not a valid filtering expression here.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"A transaction search using <code>maxevents=25</code> produces some transactions with <code>closed_txn=1</code> and some with <code>closed_txn=0</code>. What is the most likely explanation for a transaction with <code>closed_txn=0</code>?", o:["It reached exactly 25 events and was properly closed","It did not satisfy a closing condition or was evicted before it could close","It contains events from more than one <code>host</code>","It has a <code>duration</code> value greater than zero"], a:[1], e:"<code>closed_txn=1</code> indicates a transaction was closed by satisfying a constraint (such as <code>maxevents</code>, <code>maxspan</code>, <code>maxpause</code>, or <code>startswith</code>). <code>closed_txn=0</code> means the transaction was not closed by such a condition or was evicted, so it is treated as incomplete.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"The Field Extractor (IFX) offers two methods for extracting fields. Which two are they?", o:["Regular expression and Delimiter","Lookup and Calculated","Automatic and Manual","spath and rex"], a:[0], e:"The Field Extractor provides two methods: the <b>Regular expression</b> method (best for unstructured/semi-structured data) and the <b>Delimiter</b> method (best for structured data where a character such as a comma separates fields).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Managesearch-timefieldextractions", cat:"fields"},
 {q:"When using the <b>Delimiter</b> method in the Field Extractor, which of the following delimiters can it detect? (Choose all that apply.)", o:["Comma","Tab","Pipe","Newline"], a:[0,1,2], e:"The Delimiter method detects comma, tab, pipe, space, colon, and semicolon delimiters. A newline is an event boundary, not a field delimiter the FX offers.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Managesearch-timefieldextractions", cat:"fields"},
 {q:"In the Field Extractor's regular-expression method, what does the <b>Require</b> option do?", o:["Restricts the extraction so fields are only extracted from events that contain the specified required text","Forces the extracted field to be a required (non-null) field for every event","Requires the user to have the admin role before the extraction can be saved","Requires all matching events to be re-indexed before the field appears"], a:[0], e:"The Require option lets you specify a string that an event must contain for the regex to run against it. It narrows extraction to only the events that include that required text, improving accuracy and performance.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Managesearch-timefieldextractions", cat:"fields"},
 {q:"Which statement about automatic field discovery at search time is <b>true</b>?", o:["It is enabled by default, but selecting Fast mode disables it","It must be manually enabled in every search with the discover=true argument","It only works in Fast mode and is disabled in Verbose mode","It permanently adds discovered fields to the index once the search runs"], a:[0], e:"Splunk automatically discovers fields at search time and this is on by default. Fast mode disables automatic field discovery (to speed up searches), while Verbose and Smart modes allow it.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"fields"},
 {q:"Which of the following are <b>default (meta) fields</b> that Splunk adds to every event at index time? (Choose all that apply.)", o:["host","source","sourcetype","status"], a:[0,1,2], e:"host, source, and sourcetype are default fields added to each event during indexing. <code>status</code> is a custom field extracted from the data, not a default field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Usedefaultfields", cat:"fields"},
 {q:"Which command uses a <b>named capture group</b> in a regular expression to extract a new field called <code>clientip</code>?", o:["... | rex field=_raw &#96;(?&lt;clientip&gt;\\d+\\.\\d+\\.\\d+\\.\\d+)&#96;","... | erex clientip examples=&#96;192.168.1.1&#96;","... | spath input=clientip","... | lookup clientip AS ip"], a:[0], e:"The <code>rex</code> command extracts fields using regex named capture groups with the syntax <code>(?&lt;fieldname&gt;...)</code>. <code>erex</code> is example-based (you give sample values, not regex), <code>spath</code> parses structured JSON/XML, and <code>lookup</code> enriches from a table.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Rex", cat:"fields"},
 {q:"A user does not know how to write a regular expression but can provide sample values of the data they want to extract. Which command is designed for this?", o:["erex","rex","spath","makeresults"], a:[0], e:"<code>erex</code> (example-based rex) lets you supply example values of the field you want, and Splunk generates the extracting regular expression for you. <code>rex</code> requires you to write the regex yourself.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Erex", cat:"fields"},
 {q:"You have events containing JSON payloads and want to extract a nested field by its path. Which command is best suited for this?", o:["spath","rex","erex","inputlookup"], a:[0], e:"<code>spath</code> extracts fields from structured data formats such as JSON and XML by referencing the location path of the value. It is the intended tool for structured payloads rather than raw-text regex.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Spath", cat:"fields"},
 {q:"Which statements about the lookup-related search commands are <b>true</b>? (Choose all that apply.)", o:["<code>inputlookup</code> reads the contents of a lookup table and can be used as a generating command","<code>outputlookup</code> writes search results into a lookup table","<code>lookup</code> enriches events by matching fields against a lookup table","<code>inputlookup</code> is used to write new rows into an external CSV file"], a:[0,1,2], e:"<code>inputlookup</code> reads (inputs) a lookup table and can generate results at the start of a search; <code>outputlookup</code> writes results to a table; <code>lookup</code> enriches events. Writing rows is the job of <code>outputlookup</code>, not <code>inputlookup</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Inputlookup", cat:"fields"},
 {q:"Which of the following are valid <b>lookup types</b> supported by Splunk? (Choose all that apply.)", o:["CSV (file-based) lookup","KV Store lookup","Geospatial lookup","Index-time lookup"], a:[0,1,2], e:"Splunk supports CSV/file-based, KV Store, external (scripted), and geospatial lookups. There is no lookup type called \"index-time lookup\"; lookups are applied at search time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Lookup", cat:"fields"},
 {q:"A Power User creates a search-time field extraction with the Field Extractor and shares a report that uses it. A colleague opens the shared report but sees no results. What is the most likely cause?", o:["The field extraction knowledge object was not shared, or the colleague's role lacks access to the extraction or the underlying index","Search-time extractions can never be used by anyone other than their creator","The report must be rebuilt as an index-time extraction before others can run it","The colleague is running the report in Fast mode, which is the only mode that hides shared reports"], a:[0], e:"An FX extraction is a shareable knowledge object with its own permissions. If the extraction is still private (or the colleague's role can't access it or the index the data lives in), the dependent report returns no results for that user. Sharing the report alone does not share the underlying extraction or grant index access.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Managesearch-timefieldextractions", cat:"fields"},
 {q:"Which statement about <b>internal fields</b> is true?", o:["<code>_time</code> and <code>_raw</code> are internal fields prefixed with an underscore, representing the event timestamp and the raw event text","<code>host</code> and <code>source</code> are internal fields prefixed with an underscore","Internal fields are only created when you run the Field Extractor","Internal fields such as <code>_raw</code> are hidden and cannot be referenced in searches"], a:[0], e:"Internal fields are prefixed with an underscore. <code>_time</code> holds the event timestamp and <code>_raw</code> holds the original raw event text. <code>host</code> and <code>source</code> are default fields but are not underscore-prefixed internal fields, and internal fields like <code>_raw</code> can be referenced (for example by <code>rex field=_raw</code>).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Usedefaultfields", cat:"fields"},
 {q:"What is the primary purpose of a field alias in Splunk?", o:["To permanently rename a field and remove its original name","To give an existing field an additional name so it can be referenced by more than one name","To combine two fields into a single new field using an eval expression","To enrich events by matching a field against an external CSV file"], a:[1], e:"A field alias assigns an <b>additional</b> name to a field that has already been extracted. The original field name still works after aliasing; nothing is renamed or removed. Aliases are commonly used to normalize field names across different sources.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"After you create a field alias, what happens to the original field name?", o:["It is deleted and can no longer be used in searches","It continues to work; both the original name and the alias can be used","It works only in fast mode but not in verbose mode","It must be re-extracted before it can be searched again"], a:[1], e:"Aliasing adds a name; it does not replace one. The original extracted field name still functions in SPL, and the new alias name also works. This is why a field can effectively be referenced by multiple names.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"A single physical field appears under different names in two different sourcetypes (for example <code>src_ip</code> and <code>clientip</code>). You want both to be searchable as <code>source_address</code>. What must you configure?", o:["One field alias, because a single alias automatically applies to every sourcetype","One calculated field that concatenates both sourcetypes","Two field aliases, one for the field in each sourcetype","A single lookup that maps both field names to the alias"], a:[2], e:"Field aliases are tied to a specific field within a specific sourcetype (or source/host). Because the field is named differently in each of the two sourcetypes, you need a separate alias in each one to normalize both to the common name.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"Which statements about field aliases are TRUE? (Choose all that apply.)", o:["An alias can be used in SPL just like any normally extracted field","Multiple aliases can be applied to the same original field","Creating an alias overwrites the value of the original field","Aliases are frequently used to normalize field names across different sources"], a:[0,1,3], e:"Aliases behave like ordinary fields in SPL, a single field can have several aliases, and normalizing field names across sources is their classic use case. They do not overwrite or change the original field's value.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"What is the correct order of search-time knowledge object processing in Splunk?", o:["Field aliases → field extractions → calculated fields → lookups → event types → tags","Field extractions → field aliases → calculated fields → lookups → event types → tags","Field extractions → calculated fields → field aliases → lookups → tags → event types","Lookups → field extractions → field aliases → calculated fields → event types → tags"], a:[1], e:"The search-time sequence is: field extractions, then field aliases, then calculated fields, then lookups, then event types, then tags. This order explains what each object can build upon.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"Why can a field alias be referenced by a calculated field, but a lookup output field cannot?", o:["Lookup outputs are stored in props.conf while aliases are stored in transforms.conf","Field aliases are processed before calculated fields, but lookups are processed after them","Calculated fields only accept numeric inputs, and lookups return strings","Lookup outputs exist only in verbose mode, so calculated fields cannot see them"], a:[1], e:"In the search-time order, aliases run before calculated fields, so an alias already exists when the calculated field evaluates. Lookups run <b>after</b> calculated fields, so their output fields do not yet exist and cannot be used as inputs.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"In Smart Mode or Verbose Mode, after a field has been aliased, which name appears in the field list of the search results?", o:["Only the original extracted field name","The alias name","Both names shown as a single hyphenated field","Neither name until the search is saved as a report"], a:[1], e:"Once aliasing is applied, the alias name is what surfaces in the results field list in Smart or Verbose mode. The original name still works for searching, but the alias is what is displayed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutfields", cat:"aliases"},
 {q:"Which knowledge object represents the output of an eval expression that runs automatically at search time?", o:["A field alias","A calculated field","An automatic lookup","An event type"], a:[1], e:"A calculated field is a saved eval expression that Splunk runs automatically at search time. Its result is essentially the output of that eval expression, added to your events as a field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"A calculated field MUST be based on what?", o:["A field that has already been extracted (or an alias/other calculated field)","A field produced by a lookup earlier in the search","A tag or event type applied to the event","A field that is created later by the same eval expression"], a:[0], e:"A calculated field's eval expression must reference fields that already exist by the time it runs. That means already-extracted fields, field aliases, or other calculated fields. It cannot be based on lookup outputs, which are generated later.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"Which of the following can a calculated field's eval expression be based on? (Choose all that apply.)", o:["An already-extracted field","A field alias","Another calculated field","An output field returned by a lookup"], a:[0,1,2], e:"Because calculated fields run after extractions and aliases but before lookups, they can reference extracted fields, aliases, and other calculated fields. They cannot reference lookup output fields, since lookups are processed afterward.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"When is the best time to use a calculated field instead of writing the eval inline in every search?", o:["When the eval transformation is repetitive, long, or complex and reused across searches","When you need to enrich events from an external CSV file","When you want to simply rename a field to a second name","When you need to group events into a category by their characteristics"], a:[0], e:"Calculated fields shine when the same repetitive, lengthy, or complex eval expression would otherwise be retyped in many searches. Saving it as a calculated field makes the output available automatically. Renaming is an alias job; external enrichment is a lookup; categorization is an event type.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"Where in Splunk Web are both field aliases and calculated fields configured?", o:["Settings → Data inputs","Settings → Fields","Settings → Searches, reports, and alerts","Settings → Lookups"], a:[1], e:"Field aliases and calculated fields are managed under Settings → Fields, alongside field extractions. Lookups have their own Settings → Lookups area.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"In which configuration file and with what attribute prefix is a calculated field stored?", o:["transforms.conf using a <code>LOOKUP-</code> prefix","props.conf using an <code>EVAL-</code> prefix","props.conf using a <code>FIELDALIAS-</code> prefix","fields.conf using an <code>EXTRACT-</code> prefix"], a:[1], e:"Calculated fields are stored in props.conf as <code>EVAL-&lt;fieldname&gt; = &lt;eval expression&gt;</code>. The <code>FIELDALIAS-</code> prefix (also in props.conf) is for aliases, and <code>LOOKUP-</code> is for automatic lookups.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"An analyst creates a calculated field named <code>bytes_total</code> whose eval references <code>ip_country</code>, a field returned by an automatic lookup. The calculated field is empty in results. What is the most likely reason?", o:["The lookup output field is not available when the calculated field runs, because lookups are processed after calculated fields","Calculated fields cannot reference numeric fields","The field alias for <code>ip_country</code> has not been created yet","Calculated fields only work in fast mode"], a:[0], e:"Calculated fields evaluate before lookups in the search-time sequence, so <code>ip_country</code> from the lookup does not yet exist when <code>bytes_total</code> is calculated. A calculated field must be based on fields available earlier: extractions, aliases, or other calculated fields.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/definecalcfields", cat:"aliases"},
 {q:"What does a tag in Splunk knowledge objects represent?", o:["A descriptive name assigned to a specific field/value pair","A saved search that runs on a schedule","A calculated field created with the <code>eval</code> command","A time-range restriction applied to an index"], a:[0], e:"Tags let you assign descriptive names (nicknames) to specific field and value combinations, such as host, source, sourcetype, or eventtype values. This makes it easier to search for abstract values like IP addresses or ID numbers.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"Which statements about the relationship between tags and field/value pairs are TRUE? (Choose all that apply.)", o:["A single field/value pair can have multiple tags","A single tag can be applied to multiple different field/value pairs","Each field/value pair may have only one tag","Each tag may be associated with only one field/value pair"], a:[0,1], e:"Tags have a many-to-many relationship with field/value pairs. You can give one extracted field value several tags reflecting different aspects of its identity, and you can give the same tag to multiple values so a single search returns events for all of them.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"A search returns events with <code>tag=Router</code> but not with <code>tag=router</code>. What is the most likely reason?", o:["Tag names are case-sensitive, so <code>Router</code> and <code>router</code> are different tags","Tags can only be searched with the <code>tag::</code> syntax","Tags cannot be used directly in the search bar","The search time range excluded the lowercase tag"], a:[0], e:"Tag names are case-sensitive. <code>Router</code> and <code>router</code> are treated as two distinct tags, so a search on one will not match events tagged only with the other.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"You want to return only events where the <b>host</b> field has a value tagged <code>webserver</code>, ignoring that tag on any other field. Which search syntax scopes the tag to a specific field?", o:["tag::host=webserver","tag=host::webserver","host::tag=webserver","tag(host)=webserver"], a:[0], e:"Use <code>tag::&lt;field&gt;=&lt;tagname&gt;</code> to restrict a tag search to a particular field. <code>tag::host=webserver</code> matches only events where the tag <code>webserver</code> is associated with a value of the host field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"Router IP addresses are tagged <code>router</code>, and each is also tagged by location (<code>SF</code>, <code>Building1</code>, etc.). Which search returns all routers in San Francisco that are NOT in Building1?", o:["tag=router tag=SF NOT (tag=Building1)","tag=router OR tag=SF OR tag=Building1","tag=router,SF NOT Building1","router=tag SF=tag NOT Building1=tag"], a:[0], e:"Because a value can hold multiple tags, you combine tag terms with Boolean logic. <code>tag=router tag=SF NOT (tag=Building1)</code> requires both the router and SF tags while excluding events tagged Building1.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"Where in Splunk Web do you go to define and manage tags for field/value pairs?", o:["Settings &gt; Tags","Settings &gt; Data inputs","Settings &gt; Fields &gt; Field aliases","Settings &gt; Searches, reports, and alerts"], a:[0], e:"Tags are created, edited, disabled, and managed under Settings &gt; Tags. You can also apply tags directly from the field/value pairs shown in your search results.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouttagsandaliases", cat:"tags"},
 {q:"What is the primary purpose of an event type?", o:["To categorize events that match a particular search string","To schedule a report to run at a fixed interval","To rename an existing field to a friendlier name","To restrict which indexes a role can search"], a:[0], e:"An event type is a categorization system that classifies events matching a defined search string. When events match, Splunk adds an <code>eventtype</code> field/value pair to them at search time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"Which of the following CANNOT be part of the search that defines an event type? (Choose all that apply.)", o:["A pipe operator (transforming command) after a simple search","A subsearch","Boolean operators such as AND, OR, NOT","Field/value comparisons like <code>status=200</code>"], a:[0,1], e:"An event type definition must be a simple search string. It cannot include a pipe after the simple search, cannot include a subsearch, and should not reference a report with <code>savedsearch</code>. Boolean logic and field/value terms are allowed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Configureeventtypes", cat:"tags"},
 {q:"How does an event type differ from a saved search (report)?", o:["An event type has no time range and dynamically classifies matching events at search time","An event type must include a time range and runs on a schedule","An event type can contain transforming commands but a saved search cannot","An event type stores results, while a saved search only stores a name"], a:[0], e:"Unlike a saved search, an event type contains no time range and no transforming commands. It is evaluated at search time and dynamically tags any matching event with the <code>eventtype</code> field, regardless of when the events occurred.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"You run <code>sourcetype=access_combined status=200 action=purchase</code> and save it as an event type named <code>successful_purchase</code>. Afterward, how can you retrieve those events using the event type?", o:["eventtype=successful_purchase","tag=successful_purchase","| eventtype successful_purchase","savedsearch=successful_purchase"], a:[0], e:"Once saved, any event the search would return gets <code>eventtype=successful_purchase</code> added at search time. You can then search on that classification directly with <code>eventtype=successful_purchase</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"What is the fastest way to create an event type in Splunk Web from a search you just ran?", o:["Click Save As and select Event Type","Click Save As and select Report","Go to Settings &gt; Tags and add a new tag","Add <code>| makeeventtype</code> to the end of the search"], a:[0], e:"After running a search that would make a good event type, click Save As and choose Event Type. The Save As Event Type dialog lets you name the event type and optionally apply tags, a priority, and a color.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"An event matches two event types: <code>all_system_errors</code> (priority 7) and <code>critical_disk_error</code> (priority 3). Which statements are TRUE about event type priority? (Choose all that apply.)", o:["A lower priority number is a better priority, so <code>critical_disk_error</code> is listed first","The color of the better-priority event type is the one displayed for the event","A higher priority number always wins and displays its color","Priority has no effect on color or listing order"], a:[0,1], e:"When multiple event types match, Splunk orders them by priority, and a lower number is a better priority (3 beats 7). Only one color can display per event, and it is the color of the event type with the best priority value.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypepriorities", cat:"tags"},
 {q:"Which statements about tagging event types are TRUE? (Choose all that apply.)", o:["Event type values can be tagged the same way as any other field/value pair","An event can have multiple tags applied through its event types","Event types cannot be tagged because they are already knowledge objects","A tag applied to an event type may contain only lowercase letters"], a:[0,1], e:"You can tag <code>eventtype</code> field values just like any other field/value combination, and an event can have multiple tags. There is no rule that event-type tags must be lowercase, though tag names remain case-sensitive.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"In the search-time operations sequence, why can an event type's defining search NOT reference a tag?", o:["Event types are evaluated before tags, so the tags do not yet exist when event types are processed","Tags are only available in the indexing pipeline, never at search time","Tags require a pipe, which event types are not allowed to contain","Event types are evaluated after tags, so referencing a tag would create a loop"], a:[0], e:"Splunk evaluates event types before tags at search time (after lookups). Because tags are added to events only after event types are processed, an event type definition cannot reference a tag.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Abouteventtypes", cat:"tags"},
 {q:"What is the primary purpose of a search macro in Splunk?", o:["To schedule a saved search to run at a set interval","To store a reusable chunk of SPL (or a full search) that can be inserted into multiple searches","To index raw event data more efficiently","To restrict which users can run a given search"], a:[1], e:"Search macros let you save a reusable portion of SPL, or an entire search string, so you can reuse it across frequently run, similar searches instead of retyping the same logic.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"How do you reference (invoke) a search macro named <code>mymacro</code> within a search?", o:["With square brackets, like [mymacro]","With a leading pipe, like | mymacro","With backtick characters surrounding the name, like &#96;mymacro&#96;","With a dollar sign prefix, like $mymacro$"], a:[2], e:"Macros are invoked by surrounding the macro name with backtick characters, for example &#96;mymacro&#96;. Backticks distinguish a macro reference from ordinary search text.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"You want to define a search macro that accepts three arguments. How should you name the macro?", o:["mymacro[3]","mymacro(3)","mymacro$3$","mymacro=3"], a:[1], e:"When a macro takes arguments, you append the number of arguments in parentheses to the macro name. A macro accepting three arguments is named <code>mymacro(3)</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Inside a macro's definition, how are the macro's arguments referenced?", o:["By dollar-delimited names, such as $arg1$ and $arg2$","By backtick-delimited names, such as &#96;arg1&#96;","By percent-delimited names, such as %arg1%","By zero-based positions, such as [0] and [1]"], a:[0], e:"Within the macro definition, arguments are referenced by wrapping the argument name in dollar signs, for example $arg1$ and $arg2$. The values are substituted in at execution time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Where in the Splunk Web interface do you create and manage search macros?", o:["Settings &rarr; Advanced search &rarr; Search macros","Settings &rarr; Data inputs &rarr; Macros","Settings &rarr; Fields &rarr; Field extractions","Settings &rarr; Searches, reports, and alerts"], a:[0], e:"Search macros are created and edited under Settings &rarr; Advanced search &rarr; Search macros.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"A macro is defined as <code>errors_by_host(1)</code> with a definition of <code>index=web status>=500 host=$host$ | stats count by host</code>. Which statement is true? (Choose all that apply.)", o:["The macro accepts one argument that is substituted where $host$ appears","The macro contains a pipe as part of its definition","The macro must be the very first command in any search that uses it","The macro is invoked with backticks, for example &#96;errors_by_host(webserver01)&#96;"], a:[0,1,3], e:"The (1) means it takes one argument, referenced as $host$. A macro definition can include a pipe. It is invoked with backticks and the argument value passed at execution time. Macros are not required to be the first command in a search.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Which statements about pipes and search macros are correct? (Choose all that apply.)", o:["A macro definition can itself contain one or more pipe characters","A pipe can follow a macro reference in a search","A macro reference can never be preceded by a pipe","Pipes are automatically stripped out of any macro definition"], a:[0,1], e:"Macros are flexible: the definition can contain pipes, and in the invoking search a pipe can both precede and follow the macro reference. Pipes are not stripped out.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"What does an eval-based macro definition do?", o:["It runs an eval command and stores the result as a lookup","It uses an eval expression that returns an SPL string, which is then expanded into the search","It prevents the macro from ever accepting arguments","It converts the macro into a scheduled report"], a:[1], e:"An eval-based macro defines its body as an eval expression that returns a string. Splunk evaluates the expression and expands the returned SPL string into the search at run time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"What is the purpose of a validation expression on a search macro?", o:["It formats the macro's output into a table","It checks the arguments passed to the macro before the macro runs","It encrypts the argument values as they are passed","It schedules the macro to run only during business hours"], a:[1], e:"A validation expression is an eval or boolean expression used to verify that the arguments passed to the macro are acceptable before the macro executes. If validation fails, a validation error message is returned.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"A power user wants to run the same three-command SPL sequence at the start of many different searches, changing only a source type value each time. Which approach best fits this need?", o:["Create a tag for the sourcetype field","Create a search macro with one argument for the sourcetype and reference it with backticks","Create a field alias for the sourcetype","Save each search individually as a report"], a:[1], e:"A search macro with an argument is ideal for frequently run, similar searches that differ only by a passed value. Define the macro with one argument and invoke it with backticks, passing the sourcetype at execution time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Which of the following correctly invokes a macro named <code>topsales</code> that takes two arguments, <code>region</code> and <code>limit</code>?", o:["topsales(east, 10)","&#96;topsales(east, 10)&#96;","[topsales east 10]","$topsales(east,10)$"], a:[1], e:"A macro that takes arguments is invoked with backticks around the name, with the argument values in parentheses separated by commas: &#96;topsales(east, 10)&#96;.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Which statements about search macro arguments are true? (Choose all that apply.)", o:["The number of arguments is declared in the macro name using parentheses, such as name(2)","Argument values are supplied when the macro is executed","Arguments are referenced in the definition using dollar signs, such as $field$","A macro can only ever accept a single argument"], a:[0,1,2], e:"The argument count is part of the macro name in parentheses; values are passed at execution time; and arguments are referenced with dollar-delimited names in the definition. Macros can accept multiple arguments, not just one.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"A macro <code>build_search</code> is configured as an eval-based definition. At run time, Splunk evaluates the eval expression and finds it returns the string <code>index=sales | stats sum(price) by region</code>. What happens next?", o:["Splunk stores that string in a lookup table for later use","Splunk expands that returned string into the search and runs it","Splunk returns a syntax error because macros cannot contain pipes","Splunk prompts the user to confirm the returned string"], a:[1], e:"An eval-based macro returns an SPL string, which Splunk then expands in place and executes as part of the search. The returned string can include pipes.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Which of the following is the correct way to define the name of a macro that will accept four arguments?", o:["mymacro/4","mymacro(4)","mymacro{4}","mymacro:4"], a:[1], e:"The number of arguments a macro accepts is written in parentheses after the name. For four arguments the macro name is <code>mymacro(4)</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Definesearchmacros", cat:"macros"},
 {q:"Which three types of workflow actions can you create in Splunk Web?", o:["GET, POST, and Search","Link, Lookup, and Alert","Report, Alert, and Search","GET, PUT, and DELETE"], a:[0], e:"Splunk supports three workflow action types: <b>GET</b> (opens a URI/link), <b>POST</b> (sends an HTTP POST with field-value arguments), and <b>Search</b> (runs a secondary search built from field values).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"A workflow action that uses field values to launch a secondary search is which type?", o:["GET","POST","Search","Lookup"], a:[2], e:"A <b>Search</b> workflow action builds and runs a secondary search using field values from the selected event.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"How are field values inserted into a workflow action's URI or search string?", o:["With <code>%fieldname%</code> variables","With <code>$fieldname$</code> tokens","With <code>{{fieldname}}</code> placeholders","With <code>@fieldname</code> references"], a:[1], e:"Field values are inserted using <code>$fieldname$</code> token syntax. When the action runs, each token is replaced with the corresponding field value from the event.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"What information is required to create a GET workflow action? (Choose all that apply.)", o:["A URI (link) to open","The field(s) the action applies to","An HTTP POST argument list","A secondary search string"], a:[0,1], e:"A GET workflow action opens a link, so it requires a <b>URI</b> and the <b>field(s)</b> that scope where the action appears. POST arguments and a search string belong to POST and Search actions respectively.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Which field is required when configuring a <b>Search</b> workflow action?", o:["The URI to open","The POST arguments","The search string","The link method"], a:[2], e:"A Search workflow action requires a <b>search string</b>, which defines the secondary search that runs using the event's field values.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Where in Splunk Web do you create and manage workflow actions?", o:["Settings &rarr; Fields &rarr; Workflow actions","Settings &rarr; Searches, reports, and alerts","Settings &rarr; Data inputs &rarr; Actions","Settings &rarr; Advanced search &rarr; Search macros"], a:[0], e:"Workflow actions are configured under <b>Settings &rarr; Fields &rarr; Workflow actions</b>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"For a link (GET or POST) workflow action, what does the \"link method\" setting specify?", o:["Whether the link opens in the same or a new window","Whether the HTTP request uses get or post","Which field menu the action appears in","The color of the link in the menu"], a:[1], e:"The <b>link method</b> for a link action determines whether the request is sent as an HTTP <b>get</b> or <b>post</b>. Opening in the same/new window is a separate setting.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"A special token references the name of the field a user clicked when invoking a workflow action. Which token is it?", o:["<code>$@field_value$</code>","<code>$@field_name$</code>","<code>$click_field$</code>","<code>$field.name$</code>"], a:[1], e:"<code>$@field_name$</code> is a special token that resolves to the name of the field the user clicked. <code>$@field_value$</code> resolves to that field's value.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Which token resolves to the <i>value</i> of the field a user clicked to launch a workflow action?", o:["<code>$@field_name$</code>","<code>$@field_value$</code>","<code>$value$</code>","<code>$@click$</code>"], a:[1], e:"<code>$@field_value$</code> references the value of the clicked field, while <code>$@field_name$</code> references its name.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Which statements about where workflow actions can appear are true? (Choose all that apply.)", o:["An action can be shown in the field menu","An action can be shown in the event menu","An action can be shown in both the field and event menus","An action can only appear in the sidebar, never in menus"], a:[0,1,2], e:"You can configure a workflow action to appear in the <b>field menu</b>, the <b>event menu</b>, or <b>both</b>. It does not live in a sidebar.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"An analyst wants clicking a src_ip value to open a threat-intelligence website that includes that IP in its URL. Which workflow action type and configuration fits best?", o:["A Search action with a search string of <code>src_ip=$src_ip$</code>","A GET action with a URI containing <code>$src_ip$</code>","A POST action posting to the search head","A Lookup action referencing a CSV"], a:[1], e:"Opening an external website with the field value embedded in the URL is exactly what a <b>GET</b> action does. Build the URI with the <code>$src_ip$</code> token so the clicked value is substituted in.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Which statement about a Search workflow action's use of fields is TRUE?", o:["It can only use fields that are present in the event","It can reference any field in any index regardless of the event","It cannot use field tokens at all","It requires a URI rather than a search string"], a:[0], e:"A Search workflow action can <b>only use fields present in the event</b> it is launched from, since those field values populate the secondary search's tokens.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"A POST workflow action differs from a GET workflow action primarily in that it:", o:["Runs a secondary Splunk search instead of opening a link","Sends field-value arguments in an HTTP POST request","Cannot use <code>$fieldname$</code> tokens","Can only appear in the event menu"], a:[1], e:"A <b>POST</b> action sends an HTTP POST request with field-value arguments to a specified URI, whereas a GET action opens a link via URL. Both are \"link\" actions and both support tokens.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"When configuring a workflow action, which display options can you control? (Choose all that apply.)", o:["Whether the action appears in the field menu, event menu, or both","Whether the target opens in the same window or a new window","The label text shown for the action in the menu","The retention period of the indexed events"], a:[0,1,2], e:"You can set which menu(s) the action appears in, whether it opens in the same or a new window, and the label shown in the menu. Event retention is unrelated to workflow actions.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"A data model is best described as which of the following?", o:["A single saved search that is scheduled to run on an interval","A hierarchical mapping of semantic knowledge structured as one or more datasets","A CSV file used to enrich events with additional fields at search time","A collection of dashboards grouped together in a single app"], a:[1], e:"A data model is a hierarchically structured, searchable mapping of semantic knowledge about one or more sets of data. It is composed of one or more datasets and encodes domain expertise so that Pivot users can build reports without writing SPL.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"Which THREE of the following are valid types of <b>root</b> (top-level) datasets in a data model? (Choose all that apply.)", o:["Root event dataset","Root search dataset","Root transaction dataset","Root lookup dataset"], a:[0,1,2], e:"A data model can contain three kinds of root datasets: root event, root search, and root transaction. There is no \"root lookup\" dataset type. Child datasets are added beneath these roots to inherit and further constrain the data.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"A root <b>event</b> dataset is defined by which two components?", o:["A full transforming SPL search and a set of report fields","A constraint and a set of fields (attributes)","A transaction definition and a maxspan value","A lookup table and a matching output field"], a:[1], e:"A root event dataset is defined by its constraint (a simple search that has no pipes or commands beyond field/value expressions) and its fields (attributes). The constraint determines which events belong to the dataset, and the fields describe the data those events contain.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"What is the minimum requirement for the constraint of a root event dataset?", o:["It must contain at least one transforming command such as <code>stats</code>","It must include at least one constraint (a simple search expression)","It must reference an accelerated summary index","It must define at least three child datasets"], a:[1], e:"A root event dataset requires at least one constraint. The constraint is a simple search without additional pipes and search commands (for example <code>sourcetype=access_combined</code>) that identifies the events belonging to the dataset.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"Unlike a root event dataset, a root <b>search</b> dataset is defined by what?", o:["A single constraint expression with no pipes","A full SPL search string, which can include transforming commands","Only a set of auto-extracted fields","A transaction command grouping events into a single event"], a:[1], e:"A root search dataset is defined by an arbitrary SPL search string that can include transforming commands (such as <code>stats</code> or <code>eval</code>). This makes root search datasets flexible, but it also means they cannot be accelerated.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"Which user group is the Pivot tool primarily designed to serve?", o:["Splunk administrators who manage indexer clustering","Business users and other non-technical people who do not know SPL","Developers writing custom search commands in Python","Forwarder operators configuring inputs.conf"], a:[1], e:"Pivot lets users create reports, tables, charts, and dashboards from a data model without writing SPL. It is aimed at business and other non-technical users who understand their data but are not familiar with the Splunk search language.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Pivot/IntroductiontoPivot", cat:"datamodels"},
 {q:"You want to search the <code>Web</code> dataset within the <code>Web</code> data model directly from the search bar. Which SPL is correctly formed?", o:["<code>| datamodel search Web Web</code>","<code>| datamodel Web Web search</code>","<code>| tstats Web Web search</code>","<code>| pivot Web Web search</code>"], a:[1], e:"The datamodel command syntax is <code>| datamodel &lt;model_name&gt; &lt;dataset_name&gt; search</code>. So to return the events of the <code>Web</code> dataset in the <code>Web</code> data model you run <code>| datamodel Web Web search</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"Consider the search <code>| datamodel Application_State All_Application_State search</code>. Which statement correctly reads this search? (Choose all that apply.)", o:["<code>Application_State</code> is the name of the data model","<code>All_Application_State</code> is the name of the dataset within the model","The <code>search</code> keyword tells the command to return the events of that dataset","<code>All_Application_State</code> is a field being extracted from the model"], a:[0,1,2], e:"In <code>| datamodel &lt;model&gt; &lt;dataset&gt; search</code>, the first argument (<code>Application_State</code>) is the data model, the second (<code>All_Application_State</code>) is the dataset, and the <code>search</code> mode returns the dataset's events. It is not a field name.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"Which statement about data model acceleration is TRUE?", o:["Any dataset type, including root search and root transaction, can be accelerated","Only event-based (root event and their child event datasets) datasets can be accelerated","Acceleration is only available for root search datasets","Acceleration converts a data model into a lookup table"], a:[1], e:"Only event-based datasets can be accelerated. Root event datasets (and their child event datasets) qualify. Root search and root transaction datasets, and any datasets built beneath them, cannot be accelerated.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Acceleratedatamodels", cat:"datamodels"},
 {q:"A user tries to enable acceleration on a data model but the option is unavailable for a particular dataset. Which dataset types would prevent acceleration? (Choose all that apply.)", o:["Root search dataset","Root transaction dataset","Root event dataset","A child event dataset beneath a root event dataset"], a:[0,1], e:"Acceleration is only supported for event-based datasets. Root search and root transaction datasets are not event-based and therefore cannot be accelerated, whereas root event datasets and child event datasets beneath them can be.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Acceleratedatamodels", cat:"datamodels"},
 {q:"The <code>tstats</code> command is most closely associated with which capability?", o:["Running statistical queries against the tsidx summaries created by accelerated data models","Extracting fields at index time from raw events","Building visual Pivot reports through a drag-and-drop interface","Grouping events into transactions based on a shared field"], a:[0], e:"<code>tstats</code> performs statistical queries on indexed fields and, most notably, on the high-performance tsidx summary files produced by data model acceleration. Running <code>tstats</code> against accelerated summaries is dramatically faster than a raw-event search.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Tstats", cat:"datamodels"},
 {q:"Which of the following are valid data model field (attribute) types? (Choose all that apply.)", o:["Auto-extracted","Eval Expression","Lookup","Transaction"], a:[0,1,2], e:"Data model fields can be defined as auto-extracted, eval expression, lookup, regular expression, or geo-IP. \"Transaction\" is a root dataset type, not a field/attribute type.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutdatamodels", cat:"datamodels"},
 {q:"What is the primary purpose of the Splunk Common Information Model (CIM)?", o:["To compress indexed data so it consumes less disk space","To normalize data so that equivalent fields from different sources use consistent, shared field names","To encrypt raw event data as it is written to the index","To replace the need for search-time field extractions entirely"], a:[1], e:"The CIM is a shared semantic standard (a methodology) for normalizing data. It ensures that equivalent fields across different sources and sourcetypes use the same field names, making the data consistent and easy to correlate.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"How is the Splunk Common Information Model delivered and packaged for use?", o:["As a core setting enabled by default in every index","As the Splunk CIM add-on, which is a collection of predefined data models","As a standalone indexer clustering feature","As a set of scripted inputs that reformat raw data on ingest"], a:[1], e:"The CIM is delivered as the Splunk Common Information Model add-on. The add-on contains a collection of predefined data models (such as Authentication, Network Traffic, Web, and Malware) that enforce the common schema.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which knowledge objects does the CIM use to normalize data? (Choose all that apply.)", o:["Field aliases","Tags","Event types","Lookups"], a:[0,1,2,3], e:"The CIM normalizes data at search time using knowledge objects: field aliases, tags, event types, and lookups. In addition to field aliases, event types, and tags, the CIM also relies on lookups to map data to the common schema.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"A colleague claims that applying the CIM rewrites and reindexes your raw event data. Which statement is correct?", o:["Correct - CIM permanently rewrites raw events to the normalized schema","Incorrect - CIM does not change or reindex raw data; it maps existing fields to a common schema at search time","Correct - CIM reindexes only the fields that match a data model","Incorrect - CIM deletes non-matching fields but keeps the rest unchanged"], a:[1], e:"The CIM does not modify, rewrite, or reindex your raw data. It uses search-time knowledge objects to map existing fields onto a common schema, leaving the original indexed events untouched.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"By default, how is acceleration configured for the data models in the Splunk CIM add-on?", o:["Acceleration is turned on (enabled) for all data models automatically","Acceleration is turned off (disabled) by default and must be enabled by an admin","Acceleration cannot be enabled for CIM data models","Acceleration is enabled only for the Authentication data model"], a:[1], e:"In the CIM add-on, data model acceleration is turned OFF by default. An administrator must explicitly enable acceleration for the data models they want to accelerate.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which of the following are predefined data models included in the Splunk CIM add-on? (Choose all that apply.)", o:["Authentication","Network Traffic","Web","Malware"], a:[0,1,2,3], e:"The CIM add-on ships with many predefined data models, including Authentication, Network Traffic, Web, and Malware, among others. Each defines a normalized schema for a particular domain of data.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Why does normalizing data with the CIM make it easier to work across multiple data sources?", o:["Because it forces all sources to share a single index","Because equivalent fields use the same names, allowing correlation across different sources and sourcetypes","Because it removes duplicate events from every source","Because it converts all timestamps to a single time zone"], a:[1], e:"When data is normalized to the CIM, equivalent fields carry consistent names regardless of source. This lets you write a single search or report that correlates events across different sources and sourcetypes.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which Splunk premium solution relies on CIM-normalized data as its foundation?", o:["Splunk IT Service Intelligence only, never Enterprise Security","Splunk Enterprise Security","Splunk Universal Forwarder","Splunk Deployment Server"], a:[1], e:"Splunk Enterprise Security is built on top of CIM-normalized data. Its correlation searches and dashboards depend on data being mapped to the common schema, which is why CIM compliance is important for ES.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which statements accurately describe the CIM? (Choose all that apply.)", o:["It is a shared, common standard/methodology for normalizing field names","It is delivered as an add-on containing predefined data models","It maps existing fields to a common schema without altering raw data","It permanently deletes any field that does not conform to a data model"], a:[0,1,2], e:"The CIM is a common standard for normalization, is delivered as an add-on of predefined data models, and maps existing fields to a common schema without changing raw data. It does not delete non-conforming fields.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"A Power User wants to compare login activity coming from a firewall, a VPN appliance, and a Windows domain controller in a single search. How does the CIM help achieve this?", o:["It rewrites each source into a single sourcetype during indexing","It normalizes the equivalent fields (such as the user field) so one search can span all three sources","It disables the sources that do not match the Authentication data model","It requires each source to be re-onboarded as the same source"], a:[1], e:"By normalizing equivalent fields to shared names (for example, mapping various user fields to a common field), the CIM lets a single search correlate authentication events across otherwise dissimilar sources.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which statement about CIM data model acceleration is TRUE?", o:["Acceleration is always on and cannot be disabled","Acceleration is off by default; enabling it can speed up searches against large volumes of CIM data","Acceleration reindexes raw data into a faster index","Acceleration is required before any CIM field aliases will apply"], a:[1], e:"CIM data model acceleration is disabled by default. When an admin enables it, Splunk builds summaries that speed up searches and pivots against large data volumes. Acceleration is separate from the search-time normalization performed by field aliases, tags, event types, and lookups.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which of the following is NOT something the CIM does?", o:["Normalizes equivalent fields to consistent names","Provides predefined data models for common domains","Changes and reindexes the raw event data to match the schema","Uses field aliases, tags, event types, and lookups to map data"], a:[2], e:"The CIM does normalize field names, provide predefined data models, and use knowledge objects like field aliases, tags, event types, and lookups. It does NOT change or reindex the raw data.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"An administrator installs the Splunk CIM add-on and expects data model summaries to build automatically. What should they check first?", o:["Whether the raw data was reindexed by the add-on","Whether acceleration for the relevant data models has been enabled, since it is off by default","Whether the add-on deleted the original sourcetypes","Whether the CIM converted the data to a proprietary binary format"], a:[1], e:"Because acceleration is turned off by default in the CIM add-on, no summaries build until an admin enables acceleration on the desired data models. That is the first thing to verify.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"Which of the following best describes how the CIM applies to your data?", o:["It is applied at index time by rewriting events into normalized form","It is applied at search time by using knowledge objects to map fields to a common schema","It is applied only when data is exported out of Splunk","It is applied by manually renaming fields in each raw log file before ingest"], a:[1], e:"CIM normalization happens at search time. Knowledge objects (field aliases, tags, event types, and lookups) map the existing fields to the common schema when you search, without modifying the indexed raw data.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/Overview", cat:"cim"},
 {q:"After <code>transaction</code> stitches a group of events into one event, what does that single transaction event hold for its <code>_raw</code> and <code>_time</code>?", o:["The <code>_raw</code> of only the last member and the <code>_time</code> the search was run","The combined <code>_raw</code> contents of its member events and the <code>_time</code> (timestamp) of the earliest member","An empty <code>_raw</code> and the average <code>_time</code> of all members","Only the <code>_raw</code> of the earliest member and the <code>_time</code> of the latest member"], a:[1], e:"A transaction is a single event built from a group of events. It carries the <code>_raw</code> field contents of its members and inherits its <code>_time</code> from the <b>earliest</b> member. It also gains the <code>duration</code> and <code>eventcount</code> fields.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"Which statement about the performance of the <code>transaction</code> command is correct?", o:["It is lightweight and should be preferred over <code>stats</code> for all grouping","It is resource-intensive; when grouping by a unique field value is enough, <code>stats</code> is usually more efficient","It runs entirely at index time and uses no search-time memory","It costs the same as <code>eval</code> and scales freely to any data volume"], a:[1], e:"<code>transaction</code> is <b>resource-intensive</b> because it holds events in memory to stitch them together. When you can group by a unique identifier and don't need <code>_raw</code>, ordering, or <code>duration</code>, <b><code>stats</code></b> is generally faster and more scalable.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Transaction", cat:"correlate"},
 {q:"Given <code>index=web [ search index=threat | fields src_ip ]</code>, which best describes execution?", o:["The outer search runs first, then filters the subsearch's output","The subsearch runs first; its <code>src_ip</code> results become filter terms that are added to the outer search","Both run at the same time and their events are stacked together","The subsearch runs last and appends its rows beneath the main results"], a:[1], e:"A subsearch (in square brackets) runs <b>first</b>, and its results are passed up to the outer search, typically converted into <code>field=value</code> terms that filter it. Remember the defaults: 10,000 results and a 60-second runtime cap.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Search/Aboutsubsearches", cat:"correlate"},
 {q:"Which statements about subsearches are TRUE? (Choose all that apply.)", o:["They are well suited for filtering the outer search","They can be nested inside other subsearches","They always return unlimited results with no timeout","At most one subsearch may appear in any search"], a:[0,1], e:"Subsearches are great for <b>filtering</b> and <b>can be nested</b>. They are not unlimited, though: they default to 10,000 results and a 60-second timeout, and a search may contain more than one.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Search/Aboutsubsearches", cat:"correlate"},
 {q:"The <code>append</code> command adds subsearch results to the ______ of the current results, as new ______.", o:["start; columns (fields)","end; rows (events)","start; rows (events)","end; columns (fields)"], a:[1], e:"<code>append</code> attaches the subsearch results to the <b>end</b> of the current result set as additional <b>rows/events</b>. Contrast with <code>appendcols</code>, which adds subsearch results as new <b>columns/fields</b> on existing rows.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Append", cat:"correlate"},
 {q:"You use <code>appendcols</code> to add a subsearch's fields to your results. When is the output reliable rather than misleading?", o:["Only when the subsearch returns more rows than the main search","Only when the main search and subsearch return the same number of results in the same order","Only when both searches query the same index","Always, because <code>appendcols</code> matches rows on a shared key field"], a:[1], e:"<code>appendcols</code> glues subsearch values onto existing rows <b>positionally</b> (row 1 to row 1, and so on). It does <b>not</b> match on a key, so it is only reliable when both searches produce the <b>same number of rows in the same order</b>; otherwise values align with the wrong rows.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Appendcols", cat:"correlate"},
 {q:"Which statement correctly distinguishes <code>union</code> from <code>join</code>?", o:["<code>union</code> can combine two or more datasets, while <code>join</code> is limited to just two","<code>join</code> can combine unlimited datasets, while <code>union</code> handles only two","Both commands are limited to exactly two datasets","<code>union</code> matches rows on a common field, while <code>join</code> merely stacks events"], a:[0], e:"<code>union</code> combines results from <b>two or more</b> datasets (subsearches, data models, lookups, saved searches) by stacking them. <code>join</code> also combines datasets but is <b>limited to two</b> and matches on a common field. For scalable field-based correlation, <code>stats ... BY</code> is usually preferred over <code>join</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/SearchReference/Union", cat:"correlate"},
 {q:"The regular expression <code>c.t</code> is tested against these strings. Which one does it <b>fail</b> to match?", o:["<code>cat</code>","<code>c.t</code>","<code>c5t</code>","<code>coat</code>"], a:[3], e:"In regex, <code>.</code> matches <b>exactly one</b> character of any kind. <code>cat</code>, <code>c5t</code>, and even <code>c.t</code> (the dot also matches a literal period) all fit c + one char + t. <code>coat</code> fails because there are <b>two</b> characters (o, a) between the c and the t.", d:KN+"AboutSplunkregularexpressions", cat:"fields"},
 {q:"You need a regex that matches a literal period between <code>c</code> and <code>t</code> (only <code>c.t</code>, not <code>cat</code> or <code>c5t</code>). Which pattern is correct?", o:["<code>c.t</code>","<code>c\\.t</code>","<code>c*t</code>","<code>c+t</code>"], a:[1], e:"An unescaped <code>.</code> matches any character. To match a <b>literal</b> period you must escape it as <code>\\.</code>, so <code>c\\.t</code> matches only a c, a real period, and a t.", d:KN+"AboutSplunkregularexpressions", cat:"fields"},
 {q:"In the extraction regex <code>user=(?&lt;username&gt;\\w+)</code>, what becomes the <b>value</b> of the <code>username</code> field?", o:["The entire matched string <code>user=jdoe</code>","Only the text matched inside the parentheses, e.g. <code>jdoe</code>","The literal word <code>username</code>","Nothing, because <code>user=</code> is outside the group"], a:[1], e:"Only the text matched <b>inside the capture group</b> <code>( )</code> becomes the field value. The surrounding <code>user=</code> must match to locate the value but is <b>not</b> captured, so <code>username</code> = <code>jdoe</code>.", d:KN+"AboutSplunkregularexpressions", cat:"fields"},
 {q:"After you <b>manually edit</b> the generated regular expression in the Field Extractor, which capability do you lose?", o:["The ability to validate the results","The ability to save the extraction","The ability to return to the interactive field-highlighting step","The ability to apply it to a sourcetype"], a:[2], e:"Once you hand-edit the regex, Splunk can no longer map it back to the point-and-click view, so you <b>cannot return to the interactive field-highlighting step</b>. You can still validate the results and save the extraction, which is what makes the reverse claim a classic trap.", d:KN+"ExtractfieldsinteractivelywithIFX", cat:"fields"},
 {q:"A log separates values with spaces, but some values (like product names) contain spaces too. Why is the <b>Delimiter</b> method with a space delimiter risky here?", o:["Splunk does not support space as a delimiter","Fields may split in the wrong place because the delimiter also appears inside values","The Delimiter method only works on comma-separated data","Space delimiters require you to write a regex anyway"], a:[1], e:"When the delimiter character also appears <b>inside</b> a value, the Delimiter method splits at the wrong spot and misaligns fields. Comma, tab, and pipe are more reliable because they rarely occur within values.", d:KN+"ExtractfieldsinteractivelywithIFX", cat:"fields"},
 {q:"In a regular expression, what does <code>\\d{3}</code> match?", o:["Any three characters","Exactly three digit characters","A single digit, optionally repeated","Three word characters (letters, digits, or underscores)"], a:[1], e:"<code>\\d</code> matches a single digit and <code>{3}</code> is a quantifier meaning <b>exactly three</b>, so <code>\\d{3}</code> matches exactly three digits (e.g. <code>404</code>). <code>.</code> would match any character and <code>\\w</code> would match a word character.", d:KN+"AboutSplunkregularexpressions", cat:"fields"},
 {q:"Which of the following is <b>NOT</b> one of the five field types you can add to a data model dataset?", o:["Eval Expression","Geo IP","Regular Expression","Field alias"], a:[3], e:"A data model dataset supports five field types: <b>Auto-Extracted, Eval Expression, Lookup, Regular Expression, and Geo IP</b>. A field alias is a separate knowledge object, not a data model dataset field type.", d:KN+"Definedatamodelattributes", cat:"datamodels"},
 {q:"Which statement about <b>auto-extracted</b> fields in a data model is TRUE?", o:["They can be added to any dataset, root or child","They can only be added to root datasets; child datasets inherit them but cannot add new ones","They can only be added to child datasets","They must be defined with an eval expression"], a:[1], e:"You can <b>only add auto-extracted fields to root datasets</b>. Child datasets inherit those fields but cannot add new auto-extracted fields of their own.", d:KN+"Definedatamodelattributes", cat:"datamodels"},
 {q:"In what order are the fields of a data model dataset processed?", o:["Alphabetically by field name","In descending order, from the top of the list to the bottom","From the bottom of the list upward","In a random order determined at search time"], a:[1], e:"Dataset fields are processed in <b>descending order, top to bottom</b>. This matters when one field depends on another (for example, an Eval Expression field that uses auto-extracted fields), so you arrange them in the required processing order.", d:KN+"Definedatamodelattributes", cat:"datamodels"},
 {q:"How is a <b>child dataset</b> defined relative to its parent in a data model?", o:["It inherits the parent's constraints and fields, then adds more constraints to narrow the results","It is fully independent and shares nothing with the parent","It broadens the parent by removing constraints","It can only add fields, never constraints"], a:[0], e:"Child datasets <b>inherit the constraints and fields of their parent</b> and then add their own constraints to further narrow the set of events. This inheritance is what forms the data model's hierarchy.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"What must exist before a user can build a report with <b>Pivot</b>?", o:["An accelerated index","A data model, whose datasets Pivot reports against","A saved search in Fast Mode","A lookup definition"], a:[1], e:"<b>Pivot requires a data model</b>. It lets users build tables and charts from a data model's datasets without writing SPL, so with no data model there is nothing for Pivot to report on.", d:PIV, cat:"datamodels"},
 {q:"A child dataset inherits the constraint <code>index=web</code> from its parent. A designer wants that child to <i>also</i> include events from <code>index=network</code>. Why is this impossible on the child dataset?", o:["Because child datasets can only add constraints that narrow the inherited set, never broaden or remove them","Because child datasets cannot define any constraints of their own","Because only a root dataset may reference an index","Because inherited constraints can be removed but never edited"], a:[0], e:"Inheritance in a data model is <b>add-only and narrowing</b>. A child permanently inherits its parent's constraints and can only add more to further restrict the results. It can never remove or broaden an inherited constraint, so it cannot pull in events (like a different index) that the parent excluded.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"Which statements about data model dataset field <b>flags</b> are correct? (Choose all that apply.)", o:["<b>Required</b> includes only events that contain the field","<b>Optional</b> lets events that lack the field still be included","<b>Hidden</b> deletes the field from the raw events","<b>Hidden</b> keeps the field out of the Pivot user's view"], a:[0,1,3], e:"<b>Required</b> filters the dataset to events that have the field; <b>Optional</b> keeps events even when they lack it; <b>Hidden</b> only removes the field from the <b>Pivot display</b> and never deletes raw data. So the false claim is that Hidden deletes the field from events.", d:KN+"Definedatamodelattributes", cat:"datamodels"},
 {q:"Which requirements must be met to configure <b>persistent</b> data model acceleration? (Choose all that apply.)", o:["The user's role has the <code>accelerate_datamodel</code> capability","The data model is shared (app or global), not private","The data model contains all three root dataset types","A user opens the dataset in Pivot"], a:[0,1], e:"Persistent acceleration requires the <b><code>accelerate_datamodel</code> capability</b> and a <b>shared</b> (not private) data model. It does not need all three dataset types, and opening a dataset in Pivot triggers only <b>ad-hoc</b> acceleration, which is temporary.", d:KN+"Acceleratedatamodels", cat:"datamodels"},
 {q:"A user opens a data model dataset in Pivot and results speed up briefly, but no summaries are maintained afterward. What is this?", o:["Persistent data model acceleration","Ad-hoc data model acceleration","Report acceleration","Summary indexing"], a:[1], e:"Temporary acceleration triggered by <b>opening a dataset in Pivot</b>, lasting only for that session and not maintained afterward, is <b>ad-hoc acceleration</b>. <b>Persistent</b> acceleration is deliberately configured and continuously maintains tsidx summaries in the background.", d:KN+"Acceleratedatamodels", cat:"datamodels"},
 {q:"When you create a new data model and type a Title, what happens with the ID, and can it be changed later?", o:["You must type the ID manually and can edit it anytime","The ID is auto-generated from the Title and cannot be changed after creation","The ID is optional and only needed for acceleration","The ID is copied from the app name and is always editable"], a:[1], e:"As you enter the <b>Title</b>, Splunk <b>auto-generates the ID</b> from it, and the ID is <b>locked once the data model is created</b>. That permanence is why the auto-generated value matters.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"Which of the following are TRUE about creating a data model? (Choose all that apply.)", o:["Power users, not just admins, can create data models","You can assign the data model to any app you have access to","Only the Search & Reporting and Monitoring Console apps are allowed","Creation fails unless you are an admin"], a:[0,1], e:"<b>Power users</b> (not only admins) can create data models, and you can place the model in <b>any app</b> you can access. It is not restricted to Search & Reporting or the Monitoring Console, and admin is not required.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"When adding a <b>Root Event</b> dataset, which field must you enter manually, and which is generated for you?", o:["You enter the Dataset ID; the Dataset Name is generated","You enter the Dataset Name; the Dataset ID is generated from it","You must enter maxspan and maxpause values","Both the Dataset Name and Dataset ID must be typed manually"], a:[1], e:"You manually enter the <b>Dataset Name</b>, and the <b>Dataset ID auto-generates</b> from it (then locks). <code>maxspan</code>/<code>maxpause</code> belong to a Root <b>Transaction</b> dataset, not a Root Event dataset.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"Which statement about splitting data in Pivot is TRUE?", o:["You may define at most one split row and one split column","You can add multiple split rows and multiple split columns","Split columns are limited to one, though split rows are unlimited","Splitting requires an accelerated data model"], a:[1], e:"Pivot lets you add <b>multiple split rows and multiple split columns</b> (plus multiple column values and filters), which is what makes it multi-dimensional. There is no one-row/one-column limit, and acceleration is not required to split.", d:PIV, cat:"datamodels"},
 {q:"Two Splunk users on different instances want to jointly develop and test the same data model. Which built-in functionality supports this?", o:["Cloning the data model","Downloading and uploading the data model as JSON","Enabling LDAP user integration","Building it in the Search & Reporting app"], a:[1], e:"Data models can be <b>downloaded and uploaded as JSON files</b>, letting users share a model to collaboratively create, modify, and test it, even across instances. <b>Clone</b> only makes a local copy for one user, and LDAP is authentication, not collaboration.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"In which command does the <code>OVER</code> clause set the x-axis, and how does <code>BY</code> then behave?", o:["<code>stats</code> - OVER sets rows and BY sets columns","<code>chart</code> - OVER sets the x-axis and BY splits results into separate columns/series","<code>timechart</code> - OVER sets _time and BY sets the y-axis","<code>table</code> - OVER orders rows and BY hides columns"], a:[1], e:"Only <b>chart</b> uses <code>OVER</code> to choose the x-axis. Adding <code>BY</code> then splits the results into separate columns (series). Example: <code>chart count OVER host BY status</code>.", d:SR+"Chart", cat:"viz"},
 {q:"Why does <code>timechart</code> not accept an <code>OVER</code> clause?", o:["Because timechart cannot be split at all","Because its x-axis is always <code>_time</code>, so OVER is implicit","Because it only works with stats functions","Because OVER is only valid with transforming commands"], a:[1], e:"<b>timechart</b> always plots against <code>_time</code> on the x-axis (an implicit OVER _time), so you never specify OVER. You add only <code>BY</code> to split into series, and it accepts just <b>one</b> BY field.", d:SR+"Timechart", cat:"viz"},
 {q:"How does the <code>BY</code> clause differ between <code>stats</code> and <code>chart</code>?", o:["They behave identically in both commands","In stats, BY groups results into rows; in chart, BY splits results into columns/series","In stats, BY sets the x-axis; in chart, BY sets the y-axis","BY is only valid in chart, not in stats"], a:[1], e:"In <b>stats</b>, <code>BY</code> produces one <b>row</b> per unique value or combination. In <b>chart</b>, <code>BY</code> pivots those values into separate <b>columns/series</b> across the x-axis set by OVER.", d:SR+"Chart", cat:"viz"},
 {q:"According to the CIM, what does each data model consist of?", o:["A set of raw events copied into a summary index","A set of standardized field names and tags that define a domain of interest","A saved search with a fixed time range","A collection of dashboards and reports"], a:[1], e:"Each CIM data model consists of a <b>set of field names and tags</b> that define the least common denominator of a domain (such as Authentication or Web). You use these to normalize and validate data at search time.", d:CIM, cat:"cim"},
 {q:"You are making a sourcetype CIM-compliant. Its source-IP field is called <code>clientip</code>, but the data model expects <code>src</code>. What is the appropriate first step?", o:["Reindex the data with the new field name","Create a field alias mapping <code>clientip</code> to <code>src</code>","Delete the <code>clientip</code> field","Rename the sourcetype"], a:[1], e:"To normalize field <b>names</b> to the CIM standard, you create <b>field aliases</b> (for example, alias <code>clientip</code> to <code>src</code>). This is a search-time change that never modifies the raw data.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/UsetheCIMtonormalizedataatsearchtime", cat:"cim"},
 {q:"When making data CIM-compliant, what is the purpose of configuring CIM event <b>tags</b>?", o:["To permanently label the indexed events on disk","To categorize events by type so they map to the correct CIM data model","To encrypt the events","To schedule data model acceleration"], a:[1], e:"You <b>apply tags to categorize event data according to type</b>, which is how events become associated with the correct CIM data model (for example, tagging authentication events so they populate the Authentication model).", d:"https://docs.splunk.com/Documentation/CIM/latest/User/UsetheCIMtonormalizedataatsearchtime", cat:"cim"},
 {q:"Which techniques are used to normalize data so it is CIM-compliant? (Choose all that apply.)", o:["Field aliases","Field extractions","Lookups","Reindexing the raw data"], a:[0,1,2], e:"CIM normalization uses a combination of <b>field aliases, field extractions, and lookups</b> (plus tags and event types), all applied at search time. Reindexing the raw data is never required.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/UsetheCIMtonormalizedataatsearchtime", cat:"cim"},
 {q:"Besides normalizing data, which is another documented use of the CIM?", o:["Collecting data from forwarders","Validating your data against the expected schema","Replacing the need for indexes","Encrypting search results"], a:[1], e:"Documented approaches to using the CIM include normalizing data, accelerating searches, creating reports and dashboards, and <b>using the CIM to validate your data</b> against the expected data model schema.", d:CIM, cat:"cim"},
 {q:"True or False: Installing the Splunk CIM add-on collects and indexes your data for you.", o:["True - the CIM add-on ingests and indexes data","False - the CIM normalizes already-indexed data at search time; you still ingest data separately through data inputs"], a:[1], e:"<b>False.</b> The CIM does not collect or index data. You get data in through normal data inputs, and the CIM <b>normalizes that already-indexed data at search time</b>. It is a normalization layer, not a data-collection mechanism.", d:CIM, cat:"cim"},
 {q:"How does an <b>add-on</b> differ from an <b>app</b> in Splunk?", o:["An add-on is a standalone workspace with its own UI; an app only supplies field extractions","An add-on is a reusable component that supports other apps (getting data in, normalizing data) and is not typically run standalone","There is no difference; the terms are interchangeable","An add-on can only be built by Splunk, while apps are user-built"], a:[1], e:"An <b>add-on</b> is a reusable component that provides capabilities to <b>other</b> apps - getting data in, normalizing data, or supplying saved searches and macros - and is <b>not</b> typically run standalone. An <b>app</b> is a standalone workspace (like Search & Reporting) with its own UI.", d:"https://docs.splunk.com/Splexicon:Addon", cat:"cim"},
 {q:"What does a <b>Technology Add-on (TA)</b> typically provide for a specific data source?", o:["A set of executive dashboards","Field extractions, event types, tags, and aliases that normalize a sourcetype, often making it CIM-compliant","A replacement search head","A brand-new index for the data"], a:[1], e:"A <b>TA</b> packages the knowledge objects - <b>field extractions, event types, tags, and field aliases</b> - needed to parse and normalize a particular vendor's data, frequently making that sourcetype <b>CIM-compliant</b> so premium apps can use it.", d:"https://docs.splunk.com/Splexicon:Addon", cat:"cim"},
 {q:"How do Technology Add-ons relate to the CIM?", o:["They replace the CIM add-on entirely","They provide the field aliases, tags, and event types that make a source's data CIM-compliant","They accelerate all data models automatically","They manage the CIM add-on's license"], a:[1], e:"A TA does the source-specific normalization (aliases, tags, event types, extractions) that maps a vendor's fields onto the <b>CIM's standard field names and tags</b>, so the data populates the CIM data models correctly.", d:"https://docs.splunk.com/Documentation/CIM/latest/User/UsetheCIMtonormalizedataatsearchtime", cat:"cim"},
 {q:"An app is best described as which of the following?", o:["A reusable component that only supports other apps and cannot run on its own","A standalone workspace on the Splunk platform (like Search & Reporting) with its own UI and knowledge objects","A single lookup table file","A type of index bucket"], a:[1], e:"An <b>app</b> is a standalone workspace that runs on the Splunk platform and provides a UI and knowledge objects for a use case (for example, the Search & Reporting app). An <b>add-on</b>, by contrast, is a supporting component used by other apps.", d:"https://docs.splunk.com/Splexicon:App", cat:"cim"},
 {q:"Why install a vendor's Technology Add-on rather than building the field extractions yourself?", o:["Because a TA is the only way to index data","Because the TA provides prebuilt, reusable normalization (extractions, tags, aliases) for that known source, saving effort and ensuring CIM compliance","Because TAs run faster than the search head","Because a TA deletes non-compliant events"], a:[1], e:"A TA gives you <b>prebuilt, reusable</b> knowledge objects tailored to a known data source, so you don't reinvent the extractions and you get consistent <b>CIM-compliant</b> normalization out of the box.", d:"https://docs.splunk.com/Splexicon:Addon", cat:"cim"},
 {q:"True or False: An add-on such as a Technology Add-on is normally run as a standalone app with its own dashboards.", o:["True - add-ons are full standalone apps","False - add-ons are reusable supporting components, not typically run standalone"], a:[1], e:"<b>False.</b> Add-ons (including TAs) are <b>reusable components that support other apps</b> and are not typically run as standalone apps with their own UI. Standalone workspaces with dashboards are <b>apps</b>.", d:"https://docs.splunk.com/Splexicon:Addon", cat:"cim"},
 {q:"What is the key difference between a <b>field alias</b> and a <b>calculated field</b>?", o:["A field alias computes a new value; a calculated field renames a field","A field alias gives an existing field an additional name; a calculated field creates a new value using an eval expression","They are the same knowledge object","A field alias works only at index time; a calculated field works only on lookups"], a:[1], e:"A <b>field alias</b> assigns an <b>additional name</b> to an existing field (no new value; the original still works). A <b>calculated field</b> creates a field whose <b>value comes from an eval expression</b> that runs automatically at search time.", d:KN+"Addaliasestofields", cat:"aliases"},
 {q:"In the search-time sequence, why can a calculated field reference a field alias but not the reverse?", o:["Because aliases run at index time","Because field aliasing is applied before calculated fields (extraction, then aliases, then calculated fields)","Because calculated fields cannot use eval","Because aliases overwrite calculated fields"], a:[1], e:"Search-time order is extraction, then <b>field aliases</b>, then <b>calculated fields</b>. Because aliases resolve first, a calculated field's eval can use an alias - but an alias cannot depend on a calculated field created later.", d:KN+"definecalcfields", cat:"aliases"},
 {q:"What distinguishes a <b>tag</b> from an <b>event type</b>?", o:["A tag is a saved search; an event type is a label on a value","A tag is a label applied to a field=value pair; an event type is a saved search that classifies events into a named category","They are identical","A tag has a time range; an event type does not"], a:[1], e:"A <b>tag</b> is a simple <b>label attached to a field=value pair</b> (e.g. tag <code>status=404</code> as <i>error</i>). An <b>event type</b> is a <b>saved search</b> whose matching logic classifies events into a named category (with no time range or pipes).", d:KN+"Abouteventtypes", cat:"tags"},
 {q:"You want any event where <code>action=purchase</code> OR <code>action=buy</code> grouped under one reusable category you can search by name. Which knowledge object fits best?", o:["A tag on a single field=value pair","An event type whose search matches either action value","A calculated field","A workflow action"], a:[1], e:"An <b>event type</b> saves the classifying search (e.g. <code>action=purchase OR action=buy</code>) under one name, so you can later search <code>eventtype=...</code>. A <b>tag</b> labels a single field=value pair and cannot express OR logic across values on its own.", d:KN+"Abouteventtypes", cat:"tags"},
 {q:"Which workflow action type opens an external website with a clicked field value embedded in the URL?", o:["A POST action","A GET action","A Search action","A Lookup action"], a:[1], e:"A <b>GET</b> workflow action opens a <b>URL</b> with the field value inserted via a token (e.g. <code>...?ip=$src_ip$</code>). <b>POST</b> sends the value in a request body; <b>Search</b> launches a new Splunk search.", d:KN+"CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"What is the difference between a POST and a Search workflow action?", o:["POST runs a Splunk search; Search opens a URL","POST sends field values in an HTTP request body to a URI; Search launches a new Splunk search using the field values","They are identical","POST can only appear in the field menu; Search only in the event menu"], a:[1], e:"A <b>POST</b> action sends field-value arguments in an HTTP <b>POST request body</b> to an external URI. A <b>Search</b> action runs a <b>secondary Splunk search</b> using the clicked field's values. (A GET action opens a URL.)", d:KN+"CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"How does a macro WITH arguments differ from one WITHOUT, in definition and use?", o:["There is no difference in syntax","One with arguments declares the count in its name like name(2), references args as $arg$, and is called as backtick-name(v1,v2)-backtick; one without is just called as backtick-name-backtick","Argument macros use % signs; argument-less macros use backticks","Only argument macros can be shared"], a:[1], e:"A macro <b>with</b> arguments declares how many in its name - <code>name(2)</code> - references each as <code>$arg$</code> in the body, and is called like <code>&#96;name(v1,v2)&#96;</code>. A macro <b>without</b> arguments is a saved SPL snippet you call with <code>&#96;name&#96;</code>.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"What does this search return?<br><code>index=web action=purchase status=200 | stats sum(price) as revenue by product_name | sort -revenue</code>", o:["Total revenue per product for successful purchases, sorted highest to lowest","The number of purchases per product, sorted alphabetically","The single highest price across all products","Revenue per product, sorted lowest to highest"], a:[0], e:"<code>stats sum(price) as revenue by product_name</code> totals price per product; <code>sort -revenue</code> orders <b>descending</b> (the <code>-</code> means high to low). The filter limits it to successful purchases (action=purchase, status=200).", d:SR+"Sort", cat:"viz"},
 {q:"A search ends with <code>| stats count(action) as n by host</code>. What does <code>n</code> represent?", o:["The total number of events per host","The number of events per host that have a value in the action field","The number of distinct action values per host","The number of hosts"], a:[1], e:"<code>count(action)</code> counts only events that <b>have a value for action</b>, not all events. Plain <code>count</code> would count every event; <code>dc(action)</code> would count <b>distinct</b> action values.", d:SR+"CommonStatsFunctions", cat:"viz"},
 {q:"Which search returns the 10 slowest transactions (largest <code>duration</code> first)?", o:["<code>... | sort duration | head 10</code>","<code>... | sort -duration | head 10</code>","<code>... | sort 10 duration</code>","<code>... | top 10 duration</code>"], a:[1], e:"<code>sort -duration</code> sorts <b>descending</b> (largest first) and <code>head 10</code> keeps the first 10. Plain <code>sort duration</code> is ascending (smallest first), and <code>top</code> returns most-common values with counts, not the largest durations.", d:SR+"Sort", cat:"filter"},
 {q:"What is the value of <code>size</code>?<br><code>| makeresults | eval size = if(len(\"splunk\") > 3, \"big\", \"small\")</code>", o:["\"small\"","\"big\"","6","true"], a:[1], e:"<code>len(\"splunk\")</code> is 6, and 6 &gt; 3 is true, so <code>if()</code> returns its second argument, <b>\"big\"</b>.", d:SR+"Eval", cat:"filter"},
 {q:"Using the <code>where</code> command, which is the correct way to keep only events whose <code>status</code> begins with 4?", o:["<code>| where status=4*</code>","<code>| where like(status, \"4%\")</code>","<code>| where status LIKE 4*</code>","<code>| search status=4*</code>"], a:[1], e:"In <code>where</code>, wildcard matching uses <code>like()</code> with the SQL-style <code>%</code> (any characters). <code>status=4*</code> would match the literal string <code>4*</code>. The <code>search</code> command uses <code>*</code>, but the question specifies <code>where</code>.", d:SR+"Where", cat:"filter"},
 {q:"What does this produce?<br><code>index=web | timechart span=1h count by status</code>", o:["A single total count of events","One row per status value","A time series of event counts per hour, with one series per status","The most common status values"], a:[2], e:"<code>timechart</code> plots over time (x-axis = _time); <code>span=1h</code> makes hourly buckets; <code>count by status</code> creates a separate series (column) for each status value.", d:SR+"Timechart", cat:"viz"},
 {q:"What does <code>| fields - _raw host</code> do?", o:["Keeps only the _raw and host fields","Removes the _raw and host fields from the results","Renames _raw to host","Sorts the results by _raw and host"], a:[1], e:"<code>fields -</code> <b>removes</b> the listed fields. <code>fields _raw host</code> (no minus) would keep only those. Dropping <code>_raw</code> is a common way to speed up a search.", d:SR+"Fields", cat:"filter"},
 {q:"What does <code>index=web | dedup clientip</code> return?", o:["A count of events per clientip","Only the first event for each unique clientip","All events sorted by clientip","Only events where clientip is null"], a:[1], e:"<code>dedup clientip</code> keeps only the <b>first event</b> for each unique value of clientip and removes the remaining duplicates.", d:SR+"Dedup", cat:"filter"},
 {q:"What does <code>| chart count over host by status</code> produce?", o:["A table with one row per host and a separate column for each status value","A time series of counts over time","One total row across all hosts","A single number"], a:[0], e:"In <code>chart</code>, <code>over host</code> sets the x-axis (one row per host) and <code>by status</code> splits the counts into separate columns/series - one column per status value.", d:SR+"Chart", cat:"viz"},
 {q:"What is <code>tier</code> for an event where <code>bytes=1500</code>?<br><code>| eval tier = case(bytes<1000,\"low\", bytes<2000,\"mid\", 1==1,\"high\")</code>", o:["\"low\"","\"mid\"","\"high\"","null"], a:[1], e:"<code>case()</code> returns the first true branch. 1500&lt;1000 is false; 1500&lt;2000 is true, so it returns <b>\"mid\"</b>. The <code>1==1</code> default is never reached here.", d:SR+"CommonEvalFunctions", cat:"filter"},
 {q:"What does <code>| stats count as hits, dc(clientip) as visitors by url</code> return per URL?", o:["The number of events and the number of distinct client IPs for each URL","The sum of clientip values per URL","Only the most common URL","The first clientip per URL"], a:[0], e:"<code>count as hits</code> is the number of events per URL; <code>dc(clientip) as visitors</code> is the number of <b>distinct</b> client IPs per URL. Both are grouped <code>by url</code>.", d:SR+"CommonStatsFunctions", cat:"viz"},
 {q:"Which search counts failed SSH logins per source IP?", o:["<code>index=security sourcetype=linux_secure \"Failed password\" | stats count by src_ip</code>","<code>index=security sourcetype=linux_secure \"Failed password\" | stats count(src_ip)</code>","<code>index=security sourcetype=linux_secure \"Failed password\" | top src_ip</code>","<code>index=security | dedup src_ip</code>"], a:[0], e:"<code>stats count by src_ip</code> gives a count for each source IP. <code>count(src_ip)</code> returns a single number; <code>top</code> adds percentages and truncates; <code>dedup</code> only removes duplicates.", d:SR+"CommonStatsFunctions", cat:"filter"},
 {q:"A macro takes two arguments. What must its <b>Name</b> field be?", o:["<code>sessiontracker</code>","<code>sessiontracker(2)</code>","<code>sessiontracker[2]</code>","<code>sessiontracker($1,$2)</code>"], a:[1], e:"A macro that accepts arguments must declare the count in its name as <code>name(N)</code>. Two arguments means the name is <code>sessiontracker(2)</code>. The argument names (action, JSESSIONID) go in the Arguments field, without dollar signs.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"What is required for a macro to accept three arguments?", o:["The macro's name ends with <code>(3)</code>","The macro's name starts with <code>(3)</code>","The argument-count setting is 3 or more","Nothing - all macros accept any number of arguments"], a:[0], e:"The number of arguments is declared by ending the macro <b>name</b> with <code>(N)</code>. For three arguments the name ends with <code>(3)</code>. There is no separate count setting.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"When are a macro's arguments defined, and when are their values applied?", o:["Both are defined at execution time","Arguments are defined when the macro is created; their values resolve the search string at execution time","Arguments are defined at execution; values are applied at creation","Both happen when the macro is created"], a:[1], e:"You <b>define</b> the arguments when you create the macro. The <b>values</b> you pass are substituted to resolve the search string at <b>execution</b> time.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"Which is a valid use of a macro inside a search?", o:["<code>| stats if('makeMyField(oldField)')</code>","<code>| eval newField=&#96;makeMyField(oldField)&#96;</code>","<code>| &#96;makeMyField&#96;(oldField)</code> using straight quotes","<code>| \"makeMyField(oldField)\"</code>"], a:[1], e:"A macro is referenced in <b>backticks</b> and can be embedded in an eval: <code>| eval newField=&#96;makeMyField(oldField)&#96;</code>. Straight or single quotes do not invoke a macro.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"Which statement best describes a search macro?", o:["A reusable search string that must contain the full search","A reusable search string that must have a fixed time range","A reusable search string that may have a flexible time range","A reusable search string that must contain only part of the search"], a:[2], e:"A macro is a reusable chunk of SPL that <b>may have a flexible time range</b>. It can be a full search or only a portion, and its time range is not fixed.", d:KN+"Definesearchmacros", cat:"macros"},
 {q:"Creating a GET workflow action requires which of the following? (Choose all that apply.)", o:["A name for the workflow action","A URI where the user is directed at search time","A label that appears in the Event Action menu at search time","A sourcetype for the action"], a:[0,1,2], e:"A GET workflow action needs a <b>name</b>, a <b>URI</b> (with field tokens), and a <b>label</b> shown in the Event/Field Action menu. A sourcetype is not part of a workflow action's configuration.", d:KN+"CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Which statement describes a POST workflow action?", o:["It sends POST arguments to the URI location","It sends email to the URI location","Its configuration includes choosing a sourcetype","By default it appears in neither the event nor field menu"], a:[0], e:"A <b>POST</b> workflow action sends POST arguments (field values) in the request body to the specified <b>URI</b>. It does not send email or involve a sourcetype.", d:KN+"CreateworkflowactionsinSplunkWeb", cat:"workflow"},
 {q:"Data models are composed of one or more of which datasets? (Choose all that apply.)", o:["Event datasets","Search datasets","Transaction datasets","Any child of event, search, and transaction datasets"], a:[0,1,2,3], e:"A data model is built from <b>event, search, and transaction</b> root datasets, plus <b>any child datasets</b> derived from them. All four apply.", d:KN+"Aboutdatamodels", cat:"datamodels"},
 {q:"Which of the following can be used with the eval <code>tostring()</code> function? (Choose all that apply.)", o:["\"hex\"","\"commas\"","\"duration\"","\"decimal\""], a:[0,1,2], e:"<code>tostring(X, Y)</code> accepts the options <b>\"hex\"</b>, <b>\"commas\"</b>, and <b>\"duration\"</b>. There is no <b>\"decimal\"</b> option.", d:SR+"ConversionFunctions", cat:"viz"},
 {q:"A user wants to convert numeric values to strings AND sort by those values. Which should run first?", o:["It does not matter","Convert to string with eval first, then sort","Sort first, then convert to string with eval","You cannot sort and eval the same field"], a:[2], e:"<b>Sort first, then convert.</b> If you stringify the numbers first, <code>sort</code> orders them lexically (\"100\" before \"20\"), which is wrong. Sort the numeric values, then apply <code>tostring</code>.", d:SR+"Sort", cat:"viz"},
 {q:"How do you display a chart in stack mode?", o:["By using the stack command","By turning on Use Trellis Layout","By changing Stack Mode in the Format menu","You can only stack a timechart"], a:[2], e:"Stacking is a <b>formatting</b> option: open the <b>Format</b> menu on the visualization and set <b>Stack Mode</b>. It is not a command, and it is not Trellis (a separate small-multiples layout).", d:SR+"Chart", cat:"viz"},
 {q:"Which produces the same result as <code>| chart count over vendor_action by user</code>?", o:["<code>| chart count by vendor_action, user</code>","<code>| chart count over vendor_action, user</code>","<code>| chart count by vendor_action over user</code>","<code>| chart count over user by vendor_action</code>"], a:[0], e:"In <code>chart ... by X, Y</code>, the <b>first</b> field is the x-axis (the OVER field) and the <b>second</b> splits into columns (the BY field). So <code>by vendor_action, user</code> equals <code>over vendor_action by user</code>.", d:SR+"Chart", cat:"viz"},
 {q:"Using the Field Extractor's Delimiters method, which characters can serve as delimiters? (Choose all that apply.)", o:["Tabs","Pipes","Spaces","Colons"], a:[0,1,2,3], e:"The Delimiter method works with any consistent separator, including <b>tabs, pipes, spaces, commas, and colons</b>. All of these are valid.", d:KN+"ExtractfieldsinteractivelywithIFX", cat:"fields"},
 {q:"Which statement about field aliases is TRUE?", o:["Alias names replace the original field name","Field aliases can be used in lookup file definitions","Field aliases only normalize data across sources and sourcetypes","Field alias names are not case sensitive in a search"], a:[1], e:"<b>Field aliases can be used in lookup file definitions.</b> They <b>add</b> a name rather than replacing the original, they do more than only cross-source normalization, and field names are case sensitive.", d:KN+"Addaliasestofields", cat:"aliases"},
];

