const ADMIN_QUESTIONS = [
 {exam:'admin', cat:'deploy', q:"Which Splunk Enterprise component parses and indexes incoming data and stores it in indexes?", o:["Universal forwarder","Indexer","Search head","Deployment server"], a:[1], e:"The <b>indexer</b> parses, indexes, and stores incoming data, and searches its own indexed data. Forwarders send data in; search heads coordinate searches.", d:AD_DEPLOY},
 {exam:'admin', cat:'deploy', q:"What is the correct order of the Splunk data pipeline?", o:["Input → Parsing → Indexing → Search","Parsing → Input → Search → Indexing","Input → Indexing → Parsing → Search","Search → Input → Parsing → Indexing"], a:[0], e:"Data flows <b>Input → Parsing → Indexing → Search</b>. Parsing (event breaking, timestamp extraction, metadata) happens before the data is written to disk during indexing.", d:AD_DEPLOY},
 {exam:'admin', cat:'license', q:"What triggers a Splunk license violation?", o:["Running too many concurrent searches","Indexing more data in a day than your license permits","Creating too many indexes","Adding too many users"], a:[1], e:"A <b>license violation</b> occurs when you exceed your <b>licensed daily indexing volume</b> - Splunk measures the volume of data indexed per day against your license quota.", d:AD_LIC},
 {exam:'admin', cat:'confs', q:"The same setting is defined in an app's <code>local</code> and <code>default</code> directories. Which value takes effect?", o:["default always wins","local overrides default","The most recently edited file","They are merged and averaged"], a:[1], e:"In configuration layering, <b>local overrides default</b>. Never edit files in <code>default</code> (upgrades overwrite them); put your changes in <code>local</code>.", d:AD_CONF},
 {exam:'admin', cat:'confs', q:"Which command prints Splunk's merged, on-disk configuration and shows which file each setting came from?", o:["splunk show config","splunk btool <conf> list --debug","splunk diag","splunk validate"], a:[1], e:"<b>btool</b> (e.g. <code>splunk btool inputs list --debug</code>) prints the effective merged configuration and the <b>source file</b> of each setting - the go-to tool for troubleshooting precedence.", d:AD_BTOOL},
 {exam:'admin', cat:'indexes', q:"What is the correct order of the Splunk index bucket lifecycle?", o:["hot → warm → cold → frozen","warm → hot → cold → frozen","hot → cold → warm → frozen","cold → warm → hot → frozen"], a:[0], e:"Buckets age <b>hot → warm → cold → frozen</b>. Hot is writable; warm and cold are searchable but read-only; frozen data is removed from the index (deleted or archived).", d:AD_IDX},
 {exam:'admin', cat:'indexes', q:"By default, what happens to data when a bucket rolls to <b>frozen</b>?", o:["It is compressed and kept forever","It is deleted, unless a frozen archive path is configured","It is moved back to the hot bucket","It is re-indexed"], a:[1], e:"When a bucket reaches <b>frozen</b>, Splunk <b>deletes</b> it by default. If you set <code>coldToFrozenDir</code>, Splunk archives the bucket there instead of deleting it.", d:AD_RETAIN},
 {exam:'admin', cat:'users', q:"How are Splunk users granted permission to perform actions such as editing knowledge objects or running real-time searches?", o:["Directly, per individual user","Through roles, which are collections of capabilities","Through the index they can see","Through the license"], a:[1], e:"Permissions come from <b>roles</b>, which are built from <b>capabilities</b>. Users are assigned one or more roles; you don't grant capabilities to users directly.", d:AD_USERS},
 {exam:'admin', cat:'gdi', q:"You add a new data input without specifying an index. Where does the data go?", o:["It is discarded","Into the default index (main)","Into a new index named after the sourcetype","Into the _internal index"], a:[1], e:"Without an explicit index, events go to the <b>default index</b>, which is <b>main</b> unless changed. Best practice is to route data to purpose-built indexes.", d:AD_GDI},
 {exam:'admin', cat:'forwarders', q:"What is the primary difference between a universal forwarder and a heavy forwarder?", o:["The universal forwarder parses data before sending; the heavy forwarder does not","The heavy forwarder is a full Splunk instance that can parse, filter, and route data; the universal forwarder is lightweight and forwards mostly unparsed data","They are identical","The universal forwarder has a web UI"], a:[1], e:"A <b>universal forwarder</b> is a lightweight agent that forwards <b>unparsed</b> data. A <b>heavy forwarder</b> is a full Splunk Enterprise instance that can <b>parse, filter, and route</b> data before forwarding.", d:AD_UF},
 {exam:'admin', cat:'forwarders', q:"What is the role of the deployment server?", o:["It indexes data received from forwarders","It centrally distributes configuration (apps) to deployment clients such as forwarders","It runs all scheduled searches","It stores the license"], a:[1], e:"The <b>deployment server</b> centrally manages configuration by pushing <b>deployment apps</b> to <b>deployment clients</b> (like forwarders), so you don't configure each one by hand.", d:AD_DEPSRV},
 {exam:'admin', cat:'inputs', q:"Which input continuously watches a file or directory and indexes new data as it is written?", o:["oneshot","monitor","upload","batch (delete after read)"], a:[1], e:"A <b>monitor</b> input continuously watches files/directories and indexes new events as they arrive. <b>oneshot</b> and <b>upload</b> load a file a single time.", d:AD_MON},
 {exam:'admin', cat:'inputs', q:"What does the HTTP Event Collector (HEC) allow?", o:["Forwarders to send data over TCP","Applications to send data to Splunk over HTTP/HTTPS using a token","Users to run searches through REST","Indexers to replicate buckets"], a:[1], e:"<b>HEC</b> lets applications send data to Splunk directly over <b>HTTP/HTTPS</b>, authenticated with a <b>token</b> - agentless ingestion with no forwarder required.", d:AD_HEC},
 {exam:'admin', cat:'parsing', q:"Which of these happens during the <b>parsing</b> phase (not the input or indexing phase)?", o:["Reading raw bytes from the source","Breaking the stream into events, extracting timestamps, and setting index-time metadata","Writing tsidx files to disk","Running the user's search"], a:[1], e:"The <b>parsing</b> phase breaks the incoming stream into <b>events</b>, identifies <b>timestamps</b>, and applies index-time fields/metadata. Writing data to disk happens later, in the <b>indexing</b> phase.", d:AD_DEPLOY},
 {exam:'admin', cat:'parsing', q:"Which props.conf setting masks or replaces raw event text at index time using sed-style syntax?", o:["EXTRACT","SEDCMD","REPORT","FIELDALIAS"], a:[1], e:"<b>SEDCMD</b> applies sed-style substitution to <b>raw data at index time</b>, commonly used to anonymize or mask sensitive strings before the event is indexed.", d:AD_SED},
 {exam:'admin', cat:'dsearch', q:"In distributed search, what does a search head do?", o:["It stores indexed data","It dispatches searches to indexers (search peers) and merges their results","It forwards raw data to indexers","It manages licenses"], a:[1], e:"A <b>search head</b> coordinates searches: it sends the search to <b>indexers (search peers)</b>, which run it against their data, then <b>merges</b> the returned results. Multiple search heads can form a <b>search head cluster</b> for scaling.", d:AD_DSRCH},

 {exam:'admin', cat:'deploy', q:"In an indexer cluster, which node coordinates replication and tells the peer nodes what to do?", o:["A search peer","The manager node (cluster manager)","The deployment server","A license peer"], a:[1], e:"The <b>manager node</b> (cluster manager, formerly 'master node') coordinates the indexer cluster - it manages replication, tracks peer state, and tells <b>peer nodes</b> how to behave. It does not index data itself.", d:AD_CLUSTER},
 {exam:'admin', cat:'deploy', q:"Which tier collects data at the edge and forwards it, typically without indexing it?", o:["The indexing tier","The forwarding (data collection) tier","The search tier","The license tier"], a:[1], e:"The <b>forwarding / data-collection tier</b> (usually universal forwarders) gathers data at the source and ships it to indexers. The <b>indexing tier</b> parses and stores it; the <b>search tier</b> searches it.", d:AD_DEPLOY},
 {exam:'admin', cat:'license', q:"For an Enterprise license, how many warnings within a rolling 30-day window create a license violation?", o:["3","5","10","1"], a:[1], e:"An Enterprise license allows <b>5 warnings</b> in a rolling <b>30-day</b> window; the 6th (i.e., more than 5) triggers a <b>violation</b>. Each warning is issued for a day that exceeds the licensed daily volume.", d:AD_LIC},
 {exam:'admin', cat:'license', q:"In a distributed deployment, which role centrally tracks daily indexing volume for all indexers against the license?", o:["License peer","The license manager (license master)","Deployment server","Cluster manager"], a:[1], e:"The <b>license manager</b> (formerly license master) holds the license and meters usage. Indexers are configured as <b>license peers</b> that report their daily volume to it.", d:AD_LIC},
 {exam:'admin', cat:'license', q:"What is the daily indexing limit of the free Splunk license?", o:["500 MB/day","5 GB/day","No limit","1 GB/day"], a:[0], e:"The <b>Free</b> license caps indexing at <b>500 MB/day</b> and disables features like authentication, alerting, and distributed search. The 60-day Enterprise trial reverts to Free when it expires.", d:AD_LIC},
 {exam:'admin', cat:'confs', q:"In the GLOBAL configuration context, which directory has the HIGHEST precedence?", o:["$SPLUNK_HOME/etc/system/default","$SPLUNK_HOME/etc/apps/&lt;app&gt;/default","$SPLUNK_HOME/etc/apps/&lt;app&gt;/local","$SPLUNK_HOME/etc/system/local"], a:[3], e:"For the global context the order (highest to lowest) is <b>system/local</b> &gt; app local &gt; app default &gt; <b>system/default</b>. So <code>$SPLUNK_HOME/etc/system/local</code> wins.", d:AD_CONFDIR},
 {exam:'admin', cat:'confs', q:"You manually edited a .conf file on an indexer. What is generally required for the change to take effect?", o:["Nothing - changes apply instantly","A Splunk restart (some settings can be reloaded without one)","A full server reboot","Reinstalling Splunk"], a:[1], e:"Most manual <code>.conf</code> edits require a <b>Splunk restart</b> to take effect. Some settings can be reloaded via the CLI or REST endpoints, but restart is the safe default.", d:AD_CONF},
 {exam:'admin', cat:'confs', q:"Which character marks a comment line in a Splunk .conf file?", o:["//","#",";","--"], a:[1], e:"Splunk <code>.conf</code> files use <b>#</b> to begin a comment line. Comments must be on their own line, not appended to a setting.", d:AD_CONF},
 {exam:'admin', cat:'confs', q:"Which configuration file defines data inputs such as monitored files and network ports?", o:["outputs.conf","inputs.conf","props.conf","indexes.conf"], a:[1], e:"<b>inputs.conf</b> defines what data Splunk collects - monitor stanzas, network ports, scripted inputs, and HEC. <b>outputs.conf</b> defines where a forwarder sends data.", d:AD_MON},
 {exam:'admin', cat:'indexes', q:"In which configuration file are indexes defined?", o:["indexes.conf","inputs.conf","props.conf","server.conf"], a:[0], e:"<b>indexes.conf</b> defines indexes and their paths, sizes, and retention settings (e.g. <code>homePath</code>, <code>maxTotalDataSizeMB</code>, <code>frozenTimePeriodInSecs</code>).", d:AD_IDX},
 {exam:'admin', cat:'indexes', q:"Which index setting freezes data based on its AGE?", o:["maxTotalDataSizeMB","frozenTimePeriodInSecs","homePath","maxHotBuckets"], a:[1], e:"<b>frozenTimePeriodInSecs</b> rolls data to frozen once it reaches a maximum <b>age</b>. It is size-independent - use it for time-based retention policies.", d:AD_RETAIN},
 {exam:'admin', cat:'indexes', q:"Which index setting caps an index by SIZE, rolling the oldest data to frozen once exceeded?", o:["frozenTimePeriodInSecs","maxTotalDataSizeMB","coldToFrozenDir","maxWarmDBCount"], a:[1], e:"<b>maxTotalDataSizeMB</b> sets the maximum index size; when exceeded, the <b>oldest</b> bucket rolls to frozen. Whichever limit (size or age) is hit first triggers freezing.", d:AD_RETAIN},
 {exam:'admin', cat:'indexes', q:"Which bucket state is the ONLY one actively being written to?", o:["warm","cold","hot","frozen"], a:[2], e:"Only <b>hot</b> buckets are writable. When a hot bucket rolls to <b>warm</b> it becomes read-only (still searchable); <b>cold</b> is also searchable read-only; <b>frozen</b> leaves the index.", d:AD_IDX},
 {exam:'admin', cat:'users', q:"Which three roles ship by default with Splunk Enterprise?", o:["admin, power, user","root, admin, guest","super, standard, read","owner, editor, viewer"], a:[0], e:"Splunk ships with <b>admin</b>, <b>power</b>, and <b>user</b> roles by default. You typically build custom roles by inheriting from these and adjusting capabilities.", d:AD_USERS},
 {exam:'admin', cat:'users', q:"A role's <code>srchIndexesAllowed</code> setting controls what?", o:["Which apps a role can open","Which indexes members of the role are allowed to search","How many searches can run at once","The role's password policy"], a:[1], e:"<b>srchIndexesAllowed</b> lists the indexes a role may search; <b>srchIndexesDefault</b> sets which are searched when no index is specified. This is how you scope data access by role.", d:AD_USERS},
 {exam:'admin', cat:'users', q:"How can a Splunk role obtain the capabilities of another role?", o:["Roles cannot share capabilities","By inheriting (importing) one or more roles in its definition","By sharing a password","Only the admin role has capabilities"], a:[1], e:"A role can <b>inherit</b> other roles, gaining all of their capabilities and index access. This lets you layer roles instead of redefining capabilities each time.", d:AD_USERS},
 {exam:'admin', cat:'users', q:"Which external authentication methods can Splunk integrate with for user login? (Choose all that apply.)", o:["LDAP","SAML (SSO)","Multifactor authentication (MFA)","A spreadsheet upload"], a:[0,1,2], e:"Splunk supports <b>LDAP</b>, <b>SAML</b> for SSO, and <b>MFA</b> (e.g. Duo/RSA) on top of native authentication. Users are not authenticated by uploading a spreadsheet.", d:AD_USERS},
 {exam:'admin', cat:'gdi', q:"Which of the following is NOT one of Splunk's default fields?", o:["host","source","sourcetype","eventtype"], a:[3], e:"<b>host</b>, <b>source</b>, and <b>sourcetype</b> (plus <code>index</code>, <code>_time</code>, <code>linecount</code>) are default fields added at index time. <b>eventtype</b> is a <b>knowledge object</b>, not a default field.", d:AD_GDI},
 {exam:'admin', cat:'gdi', q:"What does an event's sourcetype tell Splunk?", o:["Which user ran the search","The format/type of the data, which controls how it is parsed","How large the index is","The license tier"], a:[1], e:"The <b>sourcetype</b> identifies the data's <b>format</b> (e.g. <code>access_combined</code>, <code>linux_secure</code>) and drives parsing rules - line breaking, timestamps, and field extractions.", d:AD_GDI},
 {exam:'admin', cat:'gdi', q:"To minimize index-time cost and storage, where should most field extractions happen?", o:["At index time","At search time","On the universal forwarder","In the license file"], a:[1], e:"Best practice is <b>search-time</b> extraction: it keeps indexing lean and lets you adjust extractions without re-indexing. Reserve index-time fields for cases that truly need them.", d:AD_GDI},
 {exam:'admin', cat:'forwarders', q:"Which configuration file on a forwarder specifies which indexer(s) to send data to?", o:["inputs.conf","outputs.conf","props.conf","deploymentclient.conf"], a:[1], e:"<b>outputs.conf</b> defines the receiving indexers (the <code>tcpout</code> targets) a forwarder sends to. <b>inputs.conf</b> defines what data it collects.", d:AD_FWDRCV},
 {exam:'admin', cat:'forwarders', q:"By convention, which TCP port do Splunk indexers use to receive data from forwarders?", o:["8000","8089","9997","514"], a:[2], e:"<b>9997</b> is the conventional Splunk-to-Splunk receiving port. (8000 = Splunk Web, 8089 = management/REST, 514 = common syslog.)", d:AD_FWDRCV},
 {exam:'admin', cat:'forwarders', q:"Which configuration file tells a forwarder which deployment server to poll for apps?", o:["serverclass.conf","deploymentclient.conf","outputs.conf","web.conf"], a:[1], e:"<b>deploymentclient.conf</b> points a client (forwarder) at its <b>deployment server</b>. <b>serverclass.conf</b> lives on the deployment server and maps clients to apps.", d:AD_DEPSRV},
 {exam:'admin', cat:'forwarders', q:"On a deployment server, what groups deployment clients and maps them to the apps they should receive?", o:["A server class","An index","A search head cluster","A license pool"], a:[0], e:"A <b>server class</b> defines a group of deployment clients (by filters like hostname or machine type) and the set of <b>deployment apps</b> they should get.", d:AD_DEPSRV},
 {exam:'admin', cat:'forwarders', q:"How does a universal forwarder spread data across multiple indexers to balance load?", o:["It sends everything to a single indexer","Automatic (time-based) load balancing across the configured indexers","It requires an external hardware load balancer","It cannot send to more than one indexer"], a:[1], e:"A UF performs <b>automatic load balancing</b>, switching among its list of receiving indexers on a time interval so data is spread evenly - no external load balancer needed.", d:AD_FWDRCV},
 {exam:'admin', cat:'inputs', q:"Which input type reads data from a TCP or UDP network port (for example, syslog)?", o:["Monitor input","Network input","Scripted input","HTTP Event Collector"], a:[1], e:"A <b>network input</b> listens on a <b>TCP</b> or <b>UDP</b> port. UDP is common for syslog, though sending syslog to a forwarder or syslog server and monitoring files is often preferred for reliability.", d:AD_NET},
 {exam:'admin', cat:'inputs', q:"What does a scripted input do?", o:["Continuously monitors a directory","Runs a script or program on an interval and indexes its output","Opens a raw network port","Uploads a single file through the UI"], a:[1], e:"A <b>scripted input</b> executes a script/command on a schedule and indexes whatever it writes to stdout - handy for APIs, custom metrics, or command output.", d:AD_MON},
 {exam:'admin', cat:'inputs', q:"Which CLI command indexes a single file one time, with no ongoing monitoring?", o:["splunk add monitor","splunk add oneshot","splunk start","splunk add tcp"], a:[1], e:"<b>splunk add oneshot</b> (or 'splunk add oneshot &lt;file&gt;') indexes a file <b>once</b>. <b>add monitor</b> sets up continuous monitoring instead.", d:AD_MON},
 {exam:'admin', cat:'inputs', q:"In inputs.conf, how is a file monitor stanza header written for the path /var/log?", o:["[monitor:///var/log]","[file=/var/log]","[input:/var/log]","[watch:/var/log]"], a:[0], e:"Monitor stanzas use <code>[monitor://&lt;path&gt;]</code>. For an absolute path like <code>/var/log</code> that becomes <code>[monitor:///var/log]</code> (two slashes from the scheme plus the leading slash of the path).", d:AD_MON},
 {exam:'admin', cat:'inputs', q:"HEC authenticates incoming data using what?", o:["A username and password","A token","An SSH key","The forwarder's outputs.conf"], a:[1], e:"The <b>HTTP Event Collector</b> authenticates each request with a <b>token</b>. You enable HEC, create tokens, and applications include the token in the Authorization header.", d:AD_HEC},
 {exam:'admin', cat:'parsing', q:"Which feature lets admins filter, mask, and route incoming data through a Splunk Web UI using rulesets - without hand-editing props.conf and transforms.conf?", o:["SEDCMD","Ingest Actions","Data models","Field aliases"], a:[1], e:"<b>Ingest Actions</b> provides a UI to build <b>rulesets</b> that filter, mask, and route data at ingest (including to remote storage like S3). It generates the underlying props/transforms for you.", d:AD_INGACT},
 {exam:'admin', cat:'parsing', q:"How do you drop (filter out) unwanted events at index time using props.conf and transforms.conf?", o:["Route the events to the nullQueue","Delete them later with | delete","Lower the license quota","Set SHOULD_LINEMERGE=true"], a:[0], e:"Filtering at index time routes matching events to the <b>nullQueue</b> (a transform with <code>DEST_KEY=queue</code> and <code>FORMAT=nullQueue</code>, referenced from props.conf). The <code>| delete</code> command only hides events from search, it doesn't reclaim storage.", d:AD_ROUTE},
 {exam:'admin', cat:'parsing', q:"Which props.conf setting tells Splunk where to break the incoming stream into separate events?", o:["TIME_FORMAT","LINE_BREAKER","FIELDALIAS","LOOKUP"], a:[1], e:"<b>LINE_BREAKER</b> (usually with <code>SHOULD_LINEMERGE=false</code>) defines the regex boundary Splunk uses to split raw data into individual events during parsing.", d:AD_DEPLOY},
 {exam:'admin', cat:'parsing', q:"On which components does the parsing phase occur? (Choose all that apply.)", o:["Universal forwarder","Heavy forwarder","Indexer","License manager"], a:[1,2], e:"Parsing happens on the <b>heavy forwarder</b> and the <b>indexer</b>. A <b>universal forwarder</b> forwards mostly unparsed data (parsing is offloaded downstream); the license manager plays no part in parsing.", d:AD_DEPLOY},
 {exam:'admin', cat:'dsearch', q:"In a search head cluster, which member coordinates the cluster and schedules jobs?", o:["The captain","The manager node","A license peer","The deployment server"], a:[0], e:"A search head cluster elects a <b>captain</b> that coordinates the members - scheduling searches, replicating knowledge objects, and pushing the configuration bundle. (The indexer cluster's coordinator is the manager node.)", d:AD_SHC},
 {exam:'admin', cat:'dsearch', q:"In an indexer cluster, what does the <b>replication factor</b> determine?", o:["How many searchable copies exist","How many total copies of each bucket are maintained across peers","How many search heads are allowed","The license size"], a:[1], e:"The <b>replication factor</b> is the number of <b>total copies</b> of each bucket the cluster keeps across peer nodes - it governs failure tolerance (how many peers can go down without data loss).", d:AD_CLUSTER},
 {exam:'admin', cat:'dsearch', q:"In an indexer cluster, what does the <b>search factor</b> determine?", o:["The number of SEARCHABLE copies of each bucket","The total number of copies","The number of forwarders","The retention period"], a:[0], e:"The <b>search factor</b> is the number of <b>searchable</b> copies of each bucket (copies that include the index files, not just raw data). It must be less than or equal to the replication factor; the default is 2.", d:AD_CLUSTER},
];

